window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_038"]={"n":"顾太清","dyn":"清","poems":[{"t":"游仙 其一","f":"五言古诗","c":["层台起虚馆，桂柱兰为堂。","微风从东来，吹动罗衣裳。","翻阶木芍药，薜荔当门墙。","挥杯发清兴，弦歌诵诗草。","繁星映户牖，明月照两厢。","为乐及良时，光景孰云长。"]},{"t":"游仙 其二","f":"五言古诗","c":["缥缈十二楼，上有仙人居。","左据青玉案，右拥鸿宝书。","琼瑶制危冠，芙蓉曳轻裾。","欢笑粲玉齿，从容下丹除。","俯察碧流水，清波戏朱鱼。","仰观青天云，舒卷任太虚。"]},{"t":"游仙 其三","f":"五言律诗","c":["巫山高巍巍，江水碧深杳。","中有阳台人，清容舒窈窕。","翠袖倚朱阑，颜色常美好。","我欲往从之，不见三青鸟。"]},{"t":"游仙 其四","f":"五言律诗","c":["层岩下斜日，云雾生重阴。","昏烟迷修渚，飞鸟投荒林。","清宵伫凉月，开窗弄鸣琴。","悠悠世中事，泠泠弦上音。"]},{"t":"清明雪后侍太夫人夫人游西山诸寺","f":"七言律诗","c":["三月山花尚未发，一春忽忽过清明。","云移列岫山无数，雪满丛林树有声。","怪石自成蹲虎势，老松谁与卧龙名。","晚晴碧涧添新水，归路回看暮霭平。"]},{"t":"东山草堂 其一","f":"五言律诗","c":["春水满池塘，春光入草堂。","黄茅初盖顶，紫燕欲窥梁。","卉木见真趣，图书森古香。","濛濛新雨歇，花萼婉清扬。"]},{"t":"东山草堂 其二","f":"五言律诗","c":["淑气催花萼，春风入酒樽。","日长帘幂寂，人静鸟声喧。","拂座清松影，侵阶碧藓痕。","山堂通略彴，词赋接文园。"]},{"t":"至日","f":"七言律诗","c":["衰颜暗向鬓丝催，地渐南游暖渐来。","春意待看河畔草，天心已复地中雷。","晴窗彩线盘金缕，碧海灵风破玉梅。","忽忽浮生三十四，百年行乐几倾杯。"]},{"t":"次夫子清明日双桥新寓原韵 其一","f":"五言律诗","c":["萧寺垂杨岸，明湖第几湾。","去来今日事，二十五年间。","碧瓦凄春殿，玉峰看远山。","僧窗对流水，欲往听潺潺。"]},{"t":"次夫子清明日双桥新寓原韵 其二","f":"五言律诗","c":["欲往城西寺，还须待杏花。","羸躯仍怯冷，好景不容赊。","柳眼蘸春水，渡头明晚霞。","溪山生暝色，闪闪数归鸦。"]},{"t":"宝藏寺","f":"五言律诗","c":["宝藏云峰秀，春山碧草齐。","清凉禅客室，冰玉主人题。","花雨层台上，泉声法座西。","登高渺城郭，万井晓烟低。"]},{"t":"游南谷天台寺","f":"七言律诗","c":["三月三日天台寺，日午灵风入法堂。","一段残碑哀社稷，满山春草牧牛羊。","庭前柏子参真谛，洞口桃花发妙香。","笑指他年从葬处，白云堆里是吾乡。"]},{"t":"自题道装像","f":"七言绝句","c":["双峰丫髻道家装，回首云山去路长。","莫道神仙颜可驻，麻姑两鬓已成霜。"]},{"t":"乙未元旦","f":"七言律诗","c":["声声爆竹散林鸦，烟火春城千万家。","碧瓦才临新日色，宫镫未剪去年花。","死生转觉人情切，进退须防道路差。","节物惊心同逝水，等閒谁敢负韶华。"]},{"t":"二十二日由白云观过天宁寺","f":"五言律诗","c":["遂过天宁寺，花香染客裾。","藓碑迷故事，风障护春蔬。","野草浓于绣，遥山淡若虚。","方今正望雨，宿麦及时锄。"]},{"t":"法源寺看海棠遇阮许云姜许石珊枝钱李纫兰即次壁刻钱百福老人诗韵赠之 其一","f":"五言律诗","c":["箨石文章在，风流天下传。","即看诗句好，想见老人颠。","绕座飞花雨，成阴荡碧烟。","禅房春昼静，香接逆风前。"]},{"t":"法源寺看海棠遇阮许云姜许石珊枝钱李纫兰即次壁刻钱百福老人诗韵赠之 其二","f":"五言律诗","c":["春老花盈树，丰神借客传。","绿阴随日转，红片任风颠。","邂逅江南秀，檀栾法界烟。","题诗寄同好，问讯绮窗前。"]},{"t":"游孔水用吴郡卢襄石刻诗韵","f":"七言古诗","c":["溪去山楼凡七里，平坦不烦折屐齿。","下有泉源上石堂，万佛妙相参差倚。","青苔互古不见日，森森浓绿疑无始。","龙泉古壁何年失，虎尾春冰岂可履。","夕阴水鸟上渔梁，倒映山容碧滩陊。","人生行乐须及时，花外光阴去如矢。","开元残碑嵌绝壁，幸得庐襄刻诗纪。","出山一路又看山，二水合流成漫水。","马耳东风拂面香，鸳鸯属玉惊人起。","归涂借问今何时，梨花桃花才结子。","渺渺春波万古閒，悠悠天地长如此。","偕隐何辞挽鹿车，云水遨游胜朝市。"]},{"t":"夜行翠微山麓遂宿龙泉庵","f":"七言绝句","c":["篮舆一径入云深，两两明镫过树林。","吹面不嫌山气冷，满天星斗压春岑。"]},{"t":"夏日城东泛舟归来有作","f":"七言律诗","c":["卅年不到城东去，云水空濛接远天。","野岸新蜩鸣偶尔，山门枯木尚依然。","已非昔日僧迎客，犹记当初柳系船。","一路薰风吹酒醒，重城西望隔苍烟。"]},{"t":"岁暮寄仲兄用东坡和子由苦寒见寄韵","f":"五言古诗","c":["雪后北风起，岁暮临新年。","言念客中人，何日方当还。","旅食恐不周，多病凋丰颜。","一月两寄书，一书五六篇。","告我客中事，略有好因缘。","县令与之游，我闻心喜欢。","吾兄本书生，所馀惟青毡。","明哲贵保身，思退慎进前。","出处各有时，请看墀与壖。","乐道毋忧贫，仰不愧于天。","且待春风至，万物同新鲜。","寄以敝狐裘，副以苍玉镮。","翘首望南云，新雁将北旋。"]},{"t":"四十初度","f":"七言律诗","c":["百感中来不自由，思亲此日泪空流。","雁行隔岁无消息，诗卷经年富唱酬。","过眼韶华成逝水，惊心人事等浮沤。","那堪更忆儿时候，陈迹东风有梦不。"]},{"t":"自先夫子薨逝后意不为诗冬窗检点遗稿卷中诗多唱和触目感怀结习难忘遂赋数字非敢有所怨聊记予生之不幸也兼示钊初两儿","f":"五言古诗","c":["昏昏天欲雪，围炉坐南荣。","开卷读遗编，痛极不成声。","况此衰病身，泪多眼不明。","仙人自登仙，飘然归玉京。","有儿性痴顽，有女年尚婴。","斗粟与尺布，有所不能行。","陋巷数椽屋，何异空谷情。","呜呜儿女啼，哀哀摇心旌。","几欲殉泉下，此身不敢轻。","贱妾岂自惜，为君教儿成。"]},{"t":"己亥生日哭先夫子","f":"五言律诗","c":["虚室东风冷，幽居泻泪泉。","去年同宴乐，此日隔人天。","生死原如幻，浮休岂望仙。","断肠空有恨，难寄到君前。"]},{"t":"静坐偶成","f":"七言绝句","c":["一番磨炼一重关，悟到无生心自閒。","探得真源何所论，繁枝乱叶尽须删。"]},{"t":"万松涵月歌","f":"七言古诗","c":["青天皓月悬明珠，中涵松影千万株。","森森林立无边隅，幽阴如闻天籁呼。","浓皴淡染谁所濡，粗枝密叶参天铺。","其质滑腻美且都，文登大理人所谀。","贵来方与凡石殊，天开画本应难模。","微云一抹如有无，远山掩映疑蓬壶。","其中应结仙人庐，世间日月自征徂。","惟此松能常不枯，可谓寿矣天地俱。","儿之所好能不愚，毡包载归以献吾。","自勺清泉涤泥涂，天生灵物岂容污。","斫木为架覆以幠，相对不忍离须臾。","恨不将身入画图，片石珍重抵琼瑜。"]},{"t":"潜真洞","f":"七言律诗","c":["传有真人乘鹤去，空馀老杏手亲栽。","至今深洞悬钟乳，终古阴崖长碧苔。","大道无为且游戏，谷神不死或归来。","秋风落日仙坛静，涧草岩花到处开。"]},{"t":"游潜真洞晚归度梅儿岭口占","f":"七言绝句","c":["夕阳西下乱山围，缥缈遥村暮霭霏。","游兴最嫌秋日短，马头明月照人归。"]},{"t":"夏日听道初两儿读书","f":"七言绝句","c":["翛然花木荫茅庵，一炷炉烟经半函。","閒向窗前课儿女，微风晴日诵《周南》。"]},{"t":"过访少如座中忽值雷电交作雨雹横飞闻朝阳城楼竟为雷火所毁便道往观归来赋此记之时壬寅夏四月二十二日也","f":"七言古诗","c":["岁次壬寅夏维首，庚子日斜风似吼。","是时亢旱已愆期，触热来访金闺友。","新词妙句共相论，消烦更酌尊中酒，俄然墨云挟雨飞，奇峰乱掣金蛇走。","一声霹雳震阶庭，匕箸翻盘杯落手。","旋经老妪报仓皇，神龙攫物传万口。","朝阳城楼势嵯峨，中藏灵宝天公取。","我闻此语心咄嗟，辞归不畏泥涂厚。","沿途仰视光烛天，浓烟烈焰冲牛斗。","聚观拥道如堵墙，云云默默互前后。","细思此事何休祥，雷师毋乃职其咎。","盍效昆阳助战争，一为吾皇击群丑。"]},{"t":"醉蓬莱 和黄山谷","f":"古风","c":["看秋山万叠，晓日曈昽，参差相倚。","画栋珠帘，卷高空清丽。","老桂香浓，洞箫声远，作瑶池佳会。","露缀花梢，风摇鬓影，夜来凉意。","此景人间，几曾得见，月拥寒潮，无边云水。","满酌天浆，宴鸿都道士。","秘诀长生，沧桑变化，对绮筵罗袂。","尘世纷纷，残棋一局，谁非谁是。"]},{"t":"念奴娇 和姜白石","f":"古风","c":["湖亭依旧，记从吾游者，二三仙侣。","今日莲花开已遍，翠盖团团无数。","荷露烹茶，碧筒吸酒，又听萧萧雨。","远山遮尽，片云应是催句。","欲暮白鹭成行，避人沙渚，拍拍冲天去。","争忍西风容易落，怕见断烟寒浦。","菰米随波，红衣堕露，花里谁能住。","明灯双桨，笙歌一派归路。"]},{"t":"洞仙歌 和刘一止《苕溪词》","f":"古风","c":["月明风静，问此时谁晓。","雪后初开一枝好。","爱孤山踪迹，千树横斜，临碧水，十里湖光冷照。","逋仙归去后，依旧黄昏，疏影婷婷为谁妙。","望不尽竹篱茅舍人家，断桥边、诗情空老。","任南北枝头暖相催，听玉笛声中，吹来多少。"]},{"t":"水调歌头 和周紫芝《竹坡词》","f":"古风","c":["急雨响岩壑，林木暗濛濛。","山楼四面风满，一线电光红。","雨过长天如洗，收尽无边烦暑，湿气润高峰。","坐对东山月，清影落怀中。","邀明月，酌美酒，共山翁。","不妨谈笑，尊前歌舞且从容，老去心情依旧，莫负良辰好景，去日不能重。","风月不到处，天地古今同。"]},{"t":"雨霖铃 和柳永《乐章集》","f":"古风","c":["情深语切。","奈关河远，去去难歇。","离愁正苦未尽，东方欲曙，雄鸡催发。","相送小桥流水，更霜气寒噎。","渐天外、西北峰头，晓日明明照空阔。","登高望远空伤别。","又匆匆、过了黄花节。","思量著愁何处，难拘管、断肠风月。","满目秋光，只恨重山叠巘谁设。","便织尽、锦字回文，空向盘中说。"]},{"t":"木兰花慢 和张孝祥《于湖诃》","f":"古风","c":["天高风露冷，念仙子、倚琼楼。","问云窗雾阁，朱栏翠幔，好景谁收。","玉箫歇，霓裳散，恨宝奁空掩暗增忧。","照影自临清浅，满身花影同流。","疏钟霜杵韵悠悠。","柏叶炷香篝。","记草色连天，花光似雾，历历前游。","逍遥身心物外，渺沧波、流尽古今愁。","独立莲花峰顶，下看九点齐州。"]},{"t":"满江红 第二体。和张元干《芦川词》","f":"古风","c":["绿惨红愁，东风里、杜鹃声恶。","春去也、小楼人寂，雨声偏作。","弱柳难将春思系，泪珠长向花前落。","问天涯、归梦几时来。","随风泊。","春寒重，罗衣薄。","音书断，情无著。","对残灯顾影，共谁斟酌。","昨夜雨睛知骤暖，等闲负了三春约。","卷珠帘、一望碧天长，山如削。"]},{"t":"霜叶飞 和周邦彦《片玉词》","f":"古风","c":["萋萋芳草。","疏林外、月华初上林表。","断桥流水暮烟昏，正夜凉人悄。","有沙际、寒蛩自晓。","星星三五流萤小。","见白露横空，那更对、孤灯如豆，清影相照。","昨夜梦里分明，远随征雁，迢递千里难到。","西风吹过几重山，怅故人怀抱。","想篱落、黄花开了。","尊前谁唱凄凉调。","应念我、凝情处，听雨听风，恨添多少。"]},{"t":"金缕曲 和吴文英《梦窗词》","f":"古风","c":["绝顶春风早。","见无边、红英绛萼，满枝花好。","枝上黄鹏飞过处，认取重来路杳。","此寂寂、洞天谁到。","十二栏干人倚遍，衬云容山色真容貌。","启窗户，对清照。","月华乍吐东山小。","淡银河、流云几缕，疏星多少。","翠被难禁春宵冷，况值游仙梦了。","尚残烛、灯花袅袅。","不是管弦歌舞地，更何须蜀锦花缠帽。","晨雾敛，世间晓。"]},{"t":"满庭芳 和蔡伸《友古词》","f":"古风","c":["白玉栏干，绿杨庭院，果然几净窗明。","珠帘高卷，花雨散红英。","下上双飞燕子，东风里、巧转轻迎。","连环冷、红珠斗帐，春睡惜娉婷。","梦中多少路。","山长水远，渺渺魂惊。","怕情深易感，又惹离情。","总有青鸾消息，书不尽、枉自丁宁。","终难遇，霓旌翠盖，空许愿三生。"]},{"t":"壶中天慢 和李清照《漱玉词》","f":"古风","c":["东风吹尽，便绣箔重重，春光难闭。","柳悴花憔留不住，又早清和天气。","梅子心酸，文无草长，尝遍断肠味。","将离开矣，行人千里谁寄。","帘卷四面青山，天涯望处，短屏风空倚。","宿洒新愁浑未醒，苦被鹦哥唤起。","锦瑟调弦，金钗画字，说不了心中意。","一江烟水，试问潮信来未。"]},{"t":"忆江南 题唐伯虎画江南水村五首 其一","f":"古风","c":["江南好，春草满芳洲。","山上孤亭才落日，门前高柳系归舟。","童子曳双牛。"]},{"t":"忆江南 题唐伯虎画江南水村五首 其二","f":"古风","c":["江南好，云影接山光。","负米人行莎草径，论文客坐读书堂。","晚饭菜根香。"]},{"t":"忆江南 题唐伯虎画江南水村五首 其三","f":"古风","c":["江南好，桑柘一村村。","万点鸭儿浮远岸，几家稚子候柴门。","风雨近黄昏。"]},{"t":"忆江南 题唐伯虎画江南水村五首 其四","f":"古风","c":["江南好，如练暮江清。","绕屋蒹葭秋露白，对门丘壑晚山明。","闲话豆花棚。"]},{"t":"忆江南 题唐伯虎画江南水村五首 其五","f":"古风","c":["江南好，明月绿杨梢。","茅舍孤灯犹夜织，板桥流水暗生潮。","渔火一星遥。"]},{"t":"飞雪满群山 梨花","f":"古风","c":["积雪魂轻，停云香腻，朦胧酿作微阴。","粉墙低覆，东风斜倚，晚来丝雨沉沉。","梁间闻细语，睡不稳、乌衣素襟。","玉容寂寞，霓裳舞倦，芳事这番深。","增妩媚、一枝凝泪眼，爱冰姿绰约，特费清吟。","婷婷标格，溶溶院落，春宵一刻千金。","夜凉初过雨，栏干外、轻寒不禁。","月明人静，淡烟流水无处寻。"]},{"t":"浪淘沙 偶成","f":"古风","c":["人世竞无休。","驿马耕牛。","道人眉上不生愁。","闲把丹书窗下坐，此外何求。","光景去悠悠。","岁月难留。","百年同作土鬘头。","打叠身心安稳处，顺水行舟。"]},{"t":"鹧鸪天 为孟文郡君写冬花小幅并题","f":"古风","c":["窗外寒梅报早春，山茶红绽十分新。","宓妃小试凌波袜，意态由来画不真。","天上果，世间因，花枝常对玉堂人。","夜来睡起含章殿，疏影婷婷是化身。"]},{"t":"定风波 水仙","f":"古风","c":["翠带仙仙云气凝，玉盘清露泻金精。","最是夜深人入定，相映。","满窗凉月照娉婷。","雪霁江天香更好，缥渺。","凌波难记佩环声。","一枕游仙轻似絮，无据。","梦魂空绕数峰青。"]},{"t":"入塞 盆梅","f":"古风","c":["好花枝，正清香欲破时。","似霓裳一曲，奏罢下瑶池。","红也宜，白也宜。","小楼夜凉月影移，短屏山、衾冷梦迟。","洞天深处护冰姿。","蜂不知，蝶不知。"]},{"t":"玉连环影 灯下看蜡梅","f":"古风","c":["琐琐，三五黄金颗。","为爱花香，自起移灯坐：影珊珊，舞仙坛，蜡瓣檀心，小样道家冠。"]},{"t":"桂殿秋 题画","f":"古风","c":["清露下，月明中，凤凰栖老碧梧桐。","吹箫仙子凌风去，十二楼台花自红。"]},{"t":"水龙吟 题张坤鹤老人小照，用白玉蟾《采药径》韵","f":"古风","c":["洞门深锁，烟霞苍苍，不断松杉翠。","芝田采遍，玉颜常驻，何曾落齿。","海上当年，羽衣宝髻，凤箫闲吹。","记蓬莱旧景，餐花饮月，经多少，仙家事。","渺渺长途无际。","笑世间、临歧挥泪、清风两袖，飘然到处，此生如寄。","七十年华，双眸炯炯，照人姿媚。","信谷神不死，逍遥物外，一瓢云水。"]},{"t":"卖花声 像生花","f":"古风","c":["竹簏盛来，多少像生花卉。","小年时、东风才至，街头偏卖，趁闹蛾天气。","问封姨、此情知未。","谁家妙手，特把春光游戏。","剪吴绫、点金帖翠。","一声清唱，有绣帘揭处，早惊回、绿窗人睡。"]},{"t":"最高楼 题钱元昌山水","f":"古风","c":["群峰合，天际涌青莲，飞瀑界中间。","长桥跨水通幽处，悬崖结屋伴神仙。","山出云，云渡水，水环山。","问谁凿、盘陀依断岸。","又谁种、长松临陡涧。","非人力，必天然。","林深叶密不知路，山深日冷不禁寒。","近黄昏，岚气作，罩峰巅。"]},{"t":"鹧鸪天 九日","f":"古风","c":["九日登高眼界宽，菊花才放小金团。","毂纹细浪参差水，佛髻青螺大小山。","人易老，惜流年。","茱萸插帽不成欢。","西风那管离情苫，又送征鸿下远滩。"]},{"t":"迎春乐 乙未新正四日，看钊儿等采茵蔯","f":"古风","c":["东风近日来多少。","早又见、蜂儿了。","纸鸢几朵浮天杪，点染出、晴如扫。","暖处有、星星细草。","看群儿、缘阶寻绕。","采采茵蔯芣苢，提个篮儿小。"]},{"t":"太常引 人日立春","f":"古风","c":["东风吹暖入新年。","七蓂叶，五辛盘。","人日立春天。","双彩胜、金钗并悬。","流光似水，风花无定，欢乐记从前。","羞向镜中看，衰容现、丝生鬓边。"]},{"t":"长相思 咏双獾佩","f":"古风","c":["大獾欢，小獾欢，白玉裁成两个獾。","常随佩带间。","肱相连，股相连，肱股相连心自安。","君臣父子全。"]},{"t":"鹊桥仙 梦石榴婢","f":"古风","c":["一年死别，千年幽恨，尚忆垂髫初会。","眼前难忘小腰身，侍儿里、此儿为最。","悠悠往事，不堪回首，空堕伤心清泪。","夜深时有梦魂来，梦觉后、话多难记。"]},{"t":"定风波 拟古","f":"古风","c":["花里楼台看不真，绿杨隔断倚楼人。","谁谓含愁独不见，一片，桃花人面可怜春。","芳草萋萋天远近，难问，马蹄到处总消魂。","数尽归鸦三两阵，偏衬，萧萧暮雨又黄昏。"]},{"t":"苍梧谣","f":"古风","c":["听，黄鹤楼中三两声。","仙人去，天地有余青。"]},{"t":"忆秦娥 二月十二闻角声","f":"古风","c":["情萧索，啼鸦过尽春寒作。","春寒作，春城十里，月明吹角。","哀音一片伤凄绝，黄昏更觉东风恶。","东风恶，深深庭院，重重帘幕。"]},{"t":"醉太平 闻雁","f":"古风","c":["长鸣短鸣，何来雁声。","翱翔律吕和平，发炎方北征。","人情物情，千年不更。","云中谁计邮亭，趁东风去程。"]},{"t":"海棠春 海棠","f":"古风","c":["扶头怯怯娇如滴，照银烛、千金一刻。","叶补翠云裘，花缀胭脂色。","华清浴罢疑无力，更生受、东君护惜。","亭北牡丹花，试问谁倾国。"]},{"t":"醉东风 碧桃","f":"古风","c":["玉妃装卸，天上琼枝亚。","立尽东风明月下，露井初开昨夜。","结伴阆苑飞仙，上清沦谪尘寰。","萼绿华来无定，羽衣不耐春寒。"]},{"t":"临江仙 清明前一日种海棠","f":"古风","c":["万点猩红将吐萼，嫣然回出凡尘。","移来古寺种朱门。","明朝寒食了，又是一年春。","细干柔条才数尺，千寻起自微因。","绿云蔽日树输囷。","成阴结子后，记取种花人。"]},{"t":"步蟾宫 自题画扇","f":"七言律诗","c":["沉沉院宇闲清昼，惜春去、怕春消瘦。","为花写出好精神，展纨素、粉融脂溜。","微风不许丝儿透，看颜色、年年依旧。","碧桃深处海棠开，低枝上、翠禽同宿。"]},{"t":"乳燕飞 其一","f":"古风","c":["情网丝丝绾。","问花神、飘香坠粉，是谁分判。","才见花开花又落，不念惜花人惋。","禁不得、猛风吹断。","总有游魂知旧路，奈匆匆、短劫韶光换。","空怅望，海山远。","优昙那许常相伴，照慈帏、残灯尚在，梦回不见。","十二碧城缥缈处，去去来来如幻。","倩好手、图成小卷。","尘世自生烦恼障，暮年人、咄咄书空唤。","司花史，瑶池畔。"]},{"t":"乳燕飞 其二","f":"楚辞体","c":["峰髻芙蓉绾。","月明中、翠崖千仞，洞门双判。","若有人兮翳萝薜，绰约不胜哀惋。","三十里、桃花红断。","花不长红人命脆，才人间、十二星霜换。","翛然往，碧云远。","揉蓝衫子当时伴。","梦依稀、婆娑老泪，怎禁重见。","写向图中疑是梦，梦醒谁真谁幻。","空赚得、题诗盈卷。","蓬岛昆仑嬉游处，料不闻、拍枕千呼唤。","青青草，小坟畔。"]},{"t":"法曲献仙音 题李世倬画扇，用 《清真集》韵","f":"古风","c":["云接层峦，天开画本，匹练千寻飞度。","松柏阴森，苔沙寂历，似有幽人门户。","听乱石翻涛处，时时呜骤雨。","默无语，望长桥、盘陀立尽，云雾里、布袜青鞋无阻。","缥缈玉烟霏，水风凉、涧莎柔妩。","作画当年，忆龙眠、研朱染素。","写匡庐真景，人与长风同去。"]},{"t":"暗香 谢云姜妹画梅团扇，次姜白石韵","f":"古风","c":["风枝霁色。","胜临流万点，吹开羌笛。","日暮何人，翠袖凌霜一枝摘。","写出疏香冷韵，谁得似、琅嬛仙笔。","感昨日、团扇题诗，寄我伴吟席。","南国。","夜月寂。","记庾岭五湖，千树堆积。","昔游最忆，卅载相思梦魂隔。","爱此冰纨小影，竹叶撼、一窗晴碧。","剩点检红箫谱，旧词证得。"]},{"t":"定风波 恶梦","f":"古风","c":["事事思量竟有因，半生尝尽苦酸辛。","望断雁行无定处，日暮，鹡鸰原上泪沾巾。","欲写愁怀心已醉，憔悴，昏昏不似少年身。","恶梦醒来情更怯，愁绝，花飞叶落总惊人。"]},{"t":"木兰花慢 题长洲女士李佩金《生香馆遗词》","f":"古风","c":["生香孤馆在，只燕子，旧巢安。","怅左华右竹，东张西角，噩梦难圆。","歌残曼声金缕，剩五更残月照啼鹃。","满目幽花野草，伤心落叶哀蝉。","妒花风雨护花幡，憔悴损芳颜。","有秋雁新诗，簪花法帖，种种销魂。","无端多情多病，更多愁多怨费缠绵。","一笑悬崖撒手，茫茫流水空山。"]},{"t":"凤凰台上忆吹箫 题《帝女花传奇》","f":"古风","c":["散尽天花，现身为女，韶华十五芳年。","奈才闻引凤，又赋离鸾。","烽火汹汹朝市，经几许雨僽风僝。","最伤心，盈盈弱质，半臂刀瘢。","萧然。","维摩丈室，辛苦托慈云，一榻相安。","奈晨钟暮鼓，春悄秋寒。","受尽无边烦恼，消业障、天上人间。","方能了、莲台恁时一笑因缘。"]},{"t":"高山流水 次夫子清风阁落成韵","f":"古风","c":["群山万壑引长风。","透林皋、晓日玲珑。","楼外绿阴深，凭栏指点偏东。","浑河水、一线如虹。","清凉极，满谷幽禽嘹唳，翠霭溟濛。","任海天寥阔，飞跃有无中。","云容。","看白衣苍狗，无心出、变化虚空。","细草络危岩，岩花秀妩日承红。","清风阁，高淩霄汉。","列岫如童。","待何年归去，泉石各疏慵。"]},{"t":"金缕曲 题姚珊珊小像","f":"古风","c":["何处春风面，画图中、云鬟◆鬌，羽衣轻软。","只有游魂招不得，难写寸心幽怨。","丝不尽、春蚕在茧。","离合神光空有梦，梦高唐路杳情无限。","阳台女，更谁见。","珊珊月下来何晚。","是耶非、如闻怨曲，凤箫象管。","公子凭虚卿薄命，对影徒增浩叹。","好事者、新词题满。","倩倩真真呼不应，惹相思海上三山远。","人间事，本如幻。"]},{"t":"琵琶仙 题琵琶妓陈三宝小像","f":"古风","c":["豆蔻稍头，恁年纪、值得量珠高价。","休夸燕子轻盈，腰肢更矫奼。","春院静、琵琶一曲，也应算、调高和寡。","一镜湖光，十眉山色，花底游冶。","恍疑是、苏小当年，又疑是、秋娘未曾嫁。","脂粉底干赤白，被旁人偷写。","争不似、月明湓浦，抱檀槽、感动司马。","好称珠勒金鞍，许谁迎迓。"]},{"t":"醉桃源 题墨栀子团扇寄云姜","f":"古风","c":["花肥叶大两三枝，香浮白玉卮。","轻罗团扇写冰姿，何劳腻粉施。","新雨后，好风吹，闲阶月上时。","碧天如水影迟迟，清芬晚更宜。"]},{"t":"台城路 六月廿六，云姜招游尺五庄看荷花。是日许金桥郎席题词，遂用其韵","f":"古风","c":["去天尺五韦邪杜，休疑旧梨花店。","蛛网纱窗，草迷幽径，破板红桥谁换。","池莲向暖。","听一片蝉声，绿阴不断。","点水蜻蜓，飞来又去绕花满。","登山临水寄兴，叹茫茫千古，多少恩怨。","老树婆娑，回阑曲折，笔墨频挥虚馆。","遥山在眼。","认南谷高峰，西南数遍。","归骑匆匆，夕阳天又晚。"]},{"t":"惜红衣 雨中池上，用白石韵","f":"古风","c":["电掣金蛇，云翻黑墨，风枝无力。","雨过芳塘，圆荷撼新碧。","凉风入户，动几处、骚人词客。","幽寂。","似断还连，向黄昏不息。","香消篆印，灯暗芸篝，连床乱书籍。","遥知千里泽国，楚天北。","最爱妙莲清净，法界梦中曾历。","怕颠狂风雨，洗褪好花颜色。"]},{"t":"惜琼花 雨中补种白莲，用张子野韵","f":"古风","c":["莲花白，莲叶碧。","带淤泥补种，香冷吟席。","本来清净原无色。","好雨终朝，还要终夕。","小池塘，方且窄。","涌车轮翠盖，难尽容得。","爱莲人亦情无极。","湖上盈盈，更起遥忆。"]},{"t":"珍珠帘 本意","f":"古风","c":["濛濛未许斜阳透。","荡参差、一片縠纹微绉。","闲煞小银钩，度困人长昼。","看尽落花飞尽絮，任几处、莺声轻溜。","依旧。","此好景良辰，也能消瘦。","多少苦雨酸风，障游蜂不入，晴丝难逗。","云晴曲房深，听辘轳银甃。","隔住红灯花外影，清露下、香浓金兽。","偏又。","到月照流黄，夜凉时候。"]},{"t":"凄凉犯 络纬","f":"古风","c":["梧桐落了层层叶，碧云暗度秋老。","八尺龙须，半帘月影，乍凉多少。","今年特早。","催满院、虫声又搅。","井阑边、絮絮叨叨，也似向人恼。","鼓翼瓜棚上，饮露餐花，自能常饱。","丝笼慢贮，挂房栊、最宜深悄。","不为哀音，也容易、秋衾梦觉。","隔疏窗、拌共夜雨，听到晓。"]},{"t":"冉冉云 雨中张坤鹤过访","f":"古风","c":["秋雨潇潇意难畅。","忽敲门、道人来访。","玄都客、谈论海天方丈。","全不管、世间得丧。","惟有真知最高尚。","一任他、你争我让。","把身心、且自忘忧颐养。","阅尽古今花样。"]},{"t":"垂杨 秋柳","f":"古风","c":["秋凉乍到。","便长条踠地，柔丝拂袅。","雾雨霏烟，无情不绾章台道。","梦回十二红楼悄。","小桥外、夕阳遍照。","阅行人、一树弯腰，带六朝风调。","经过春风多少。","任月白天空，惊乌三绕。","谢尽繁华，长堤落叶无人扫。","青蛾不是当初貌。","更对着、断肠衰草。","萧疏客舍，寒蝉声渐老。"]},{"t":"望月婆罗门引 中元步月","f":"古风","c":["海棠花底，乱蛩啼遍小阑干。","月阴云净天宽。","立尽梧桐影里，深草露华寒。","听哀音几处，痛哭中元。","蒿灯细然。","荡万点、小金丸。","看到香消火灭，过眼浮烟。","秋风庭院，破尘梦、清磬一声圆。","南窗下、剪烛更阑。"]},{"t":"临江仙慢 白云观看坤鹤老人受戒","f":"古风","c":["阆苑会仙侣，金钟低度，玉磬初敲。","松阴下、仙音一派风飘。","笙箫。","早人语静，幢幡绕，寿字香烧。","张坤鹤，被霞裾鹤氅，宝髻云翘。","消摇。","同登道箓，看取天外鸾轺。","拥无边、沧海皓月银涛。","相邀。","涤除玄览，瑶池宴，已熟蟠桃。","功成后，行不言之教，万物根苗。"]},{"t":"新雁过妆楼 闻雁","f":"古风","c":["冷入帘帏。","西风送、一行旅雁南飞。","碧天如水，去路远趁斜晖。","云外寄书秋浩荡，月中连翼影参差。","共依依。","楚江芦岸，霜点毛衣。","秋容三分过半，恰寒砧韵咽，画角声悲。","黄花消息，露华暗满东篱。","山程水程万里，动几处、离人双泪垂。","重阳近，更乱虫声里，良夜何其。"]},{"t":"浣溪沙 中秋作","f":"七言古诗","c":["楼外秋寒知不知。","看看又到菊花时。","半窗白日影如驰。","去日已多来日少，来何欢喜去何悲。","且斟美酒对清辉。"]},{"t":"醉春风 自题画梅，用竹叶庵韵","f":"古风","c":["暖室香成阵。","老干妆红粉。","梅花窗外月明时，忖。","忖。","忖。","山意冲寒，湖光压碧，乍传春信。","绿点苔衣衬。","不许风吹损。","梦为蝴蝶到罗浮，问。","问。","问。","疏影横斜，暗香浮动，谁能拘紧。"]},{"t":"鹧鸪天 冬夜听夫子论道，不觉漏三商矣。盆中残梅香发，有悟赋此","f":"古风","c":["夜半谈经玉漏迟，生机妙在本无奇。","世人莫恋花香好，花到香浓是谢时。","蜂酿蜜，茧抽丝。","功成安得没人知。","华鬉阅尽恒沙劫，雪北香南觅导师。"]},{"t":"山鬼谣 题管夫人画竹","f":"古风","c":["认濛濛、万竿修竹，绿烟一片清冷。","楚天不问云深浅，日暮凄其风劲。","吹不定。","望不尽、满川秋水寒光迥。","露澄烟暝。","更无数青山，无边青霭，天际远峰映。","伤心更，写出苍梧旧景。","美人芳草谁省。","千梢万叶矜当世，闲了鸥波小艇。","尘梦醒。","剩两岸、娟娟瘦玉摇江影。","神游目骋。","算只有南楼，老人画法，千古妙相并。"]},{"t":"定风波 古春轩老人有《消夏集》，徵咏夜来香、鹦哥，纫素馨以为架者，盖云林手制也","f":"古风","c":["斑竹帘栊亚字栏，素馨花发晚风妍。","清遣芸窗邀女伴，堪羡。","闺中造物有花仙。","妙手制成花架子，架起。","鹦哥也是好花穿。","闲向绿槐阴里挂，长夏。","悄无人处一声蝉。"]},{"t":"浪淘沙 冰灯","f":"古风","c":["宝塔十三层。","楼观飞惊。","清凉世界住飞琼。","藐姑射仙冰雪貌，玉佩瑽琤。","巧制太轻盈。","细缕坚冰。","六鳌海上势崚嶒。","看到雪消明月夜，万点寒星。"]},{"t":"金缕曲 题《花帘词》寄吴蘋香女士，用本集中韵","f":"楚辞体","c":["何幸闻名早。","爱春蚕、缠绵作茧，丝丝萦绕。","织就七襄天孙锦，彩线金针都扫。","隔千里、系人怀抱。","欲见无由缘分浅，况卿乎、与我年将老。","莫辜负，好才调。","落花流水难猜料。","正无妨、冰弦写怨，云笺起草。","有美人兮倚修竹，何日轻舟来到。","叹空谷、知音偏少。","只有莺花堪适兴，对湖光山色舒长啸。","愿寄我，近来稿。"]},{"t":"贺圣朝 秧歌","f":"古风","c":["满街锣鼓喧清昼。","任狂歌狂走。","乔装艳服太妖淫，尽京都游手。","插秧种稻，何曾能够，古遗风不守。","可怜浪费好时光，负良田千亩。"]},{"t":"长相思 为陈素安姊画红梅小幅","f":"古风","c":["深胭脂。","浅胭脂。","细蕊繁英压满枝。","清香入梦迟。","乍开时。","欲谢时。","铁干铮铮瘦影欹。","东风著意吹。"]},{"t":"江城子 记梦","f":"古风","c":["烟笼寒水月笼沙。","泛灵槎。","访仙家。","一路清溪双桨破烟划。","才过小桥风景变，明月下，见梅花。","梅花万树影交加。","山之涯。","水之涯。","淡宕湖天韶秀总堪夸。","我欲遍游香雪海，惊梦醒，怨啼鸦。"]},{"t":"一痕沙 冬夜听秋虫作","f":"古风","c":["金鼎重薰甲煎。","锦帐双垂银蒜。","床下小虫鸣。","作秋声。","斗室深沉寒漏。","一穗残灯如豆。","风竹扫闲庭。","细听听。"]},{"t":"沁园春 桃花源次夫子韵","f":"古风","c":["一夜东风，吹醒桃花，春到人间。","趁月朗风柔，扁舟一棹，绿波渺渺，花影珊珊。","洞里有天，天涯有路，风月莺花终古闲。","惜春去，怕桃花结子，冷落神仙。","此中大好盘桓。","有人面、依稀似旧年。","怅前度刘郎，如今老去，玄都种树，树已含烟。","日暮天寒，露滋风损，开落无心谁与传。","认不出，似婷婷倩女，素魄娟妍。"]},{"t":"水调歌头 谢古春轩老人见赠竹根仙槎","f":"古风","c":["蓬莱渺何许，仙侣泛仙舟。","海天寥阔，千里万里御风游。","左右青童玉女，上下霓旌翠盖，花雨散中洲。","合奏钧天乐，王母驾灵虬。","松为篷，桂为楫，破云流。","翔龙翥凤，盘曲古节几春秋。","恍若轻身遐举，泛览十洲三岛，对此可忘忧。","欲借长风便，吹我到杭州。"]},{"t":"苍梧谣 正月三日自题墨牡丹扇","f":"古风","c":["侬。","淡扫花枝待好风。","瑶台种，不作可怜红。"]},{"t":"鹧鸪天 题南楼老人秋水图","f":"古风","c":["瑟瑟凉风入小池。","红衣落尽翠离披。","双螯荐酒重阳近，一鹭冲天夕照迟。","白露结，碧云垂。","波沈菰米动涟漪。","可怜秋色无多日，留得残荷听几时。"]},{"t":"风光好 天宁寺看花望西山积雪","f":"古风","c":["好东风。","暖融融。","花坞山茶照眼红。","醉游蜂。","绿烟一带前村柳。","春如绣。","积雪西山万万重。","玉芙蓉。"]},{"t":"诉衷情 春日","f":"古风","c":["忙中己过早春时。","病因强支持。","东风簸弄花事，细柳袅烟丝。","深院宇，日迟迟。","绣帘垂。","杏花消息，乍暖微寨，燕子先知。"]},{"t":"鹧鸪天 傀儡","f":"古风","c":["傀儡当场任所为。","讹传故事惑痴儿。","李唐赵宋皆无考，妙在妖魔变化奇。","驾赤豹，从文狸。","衣冠楚楚假威仪。","下场高挂成何用，刻木牵丝此一时。"]},{"t":"江城子 题日酣川静野云高石画","f":"古风","c":["日酣川静野云高。","远山遥。","碧迢迢。","千里孤帆一叶任风飘。","莫话滩头波浪险，波平处，自逍遥。","昏昏天地太无聊。","系长条。","钓鲸鳌。","且对江光山色酌香醪。","其奈眼看人尽醉，悲浊世，续离骚。"]},{"t":"清平乐 二月十日，金夫人惠芸苔菜，予不食此味廿六年矣。遂以短词记之","f":"古风","c":["春风春雨。","酝酿春如许。","三十六陂芳草路。","尚记昔年游处。","漠漠翠羽金英。","菜花开近清明。","好是江南二月，者般滋味香清。"]},{"t":"浪淘沙 春日同夫子游石堂，回经慈溪，见鸳鸯无数，马上成小令","f":"古风","c":["花木自成蹊。","春与人宜。","清流荇藻荡参差。","小鸟避人栖不定，扑乱杨枝。","归骑踏香泥。","山影沈西。","鸳鸯冲破碧烟飞。","三十六双花样好，同浴清溪。"]},{"t":"忆秦娥 白海棠","f":"古风","c":["春将暮。","绿阴一树丝丝雨。","丝丝雨。","海棠花放，十分娇素。","仙仙似惹凌波步。","娟娟又怕东风妒。","东风妒。","满枝冰雪，淡烟轻雾。"]},{"t":"探春慢 春阴","f":"古风","c":["九十韶光，清明过了，一年春色将尽。","雨洒芳田，烟霏深院，偏是轻阴惹困。","燕子来时候，已辜负、几番花信。","海棠零落闲庭，风飘万点成阵。","懊恼留春不住，算只有陌头，杨柳勾引。","漠漠情怀，恹恹天气，况又阴晴无准。","多少伤心处，奈岁月、暗催双鬓。","对酒当歌，回头往事休论。"]},{"t":"鹧鸪天 上巳同夫子游丰台","f":"古风","c":["南郭同游上巳天。","小桥流水碧湾环。","海棠婀娜低红袖，杨柳轻盈荡绿烟。","花艳艳，柳翩翩。","断魂花柳又春残。","夕阳影里双飞蝶，相逐东风下菜田。"]},{"t":"金缕曲 咏白海棠","f":"古风","c":["洞户深深掩。","笑世间、浓脂腻粉，那般妆点。","认取朦胧明月下，不许东风偷飐。","偏触动、词人系念。","昨日微阴今日雨，好春光、有限无余欠。","肯为我，一时暂。","冰绡雾縠谁烘染。","爱依依、柔条照水，靓妆清艳。","墙角绿阴栏外影，印上芸窗冰簟。","隔一片、轻阴黯淡。","不是封姨情太薄，是盈盈、树底魂难忏。","春欲暮，易生感。"]},{"t":"好事近","f":"古风","c":["将近牡丹时，已是海棠零落。","祝尔早些开者，怕东风耽搁。","匆匆古寺暂分襟，执手更相约。","十日重来恰好，订看花南郭。"]},{"t":"念奴娇 木香花","f":"古风","c":["柔条细叶，爱微风吹起，一棚香雾。","剪到牡丹春已尽，又把春光钩住。","琐碎繁英，零星小朵，枝上摇清露。","飞琼何事，羽衣似斗轻絮。","昨夜入梦香清，晓来香已透，碧窗朱户。","蝶浪蜂憨无检束，绕遍深丛处处。","璎珞垂珠，绿云蔽日，谁忍攀条去。","来年春日，愿教香雪盈树。"]},{"t":"玉楼春 廿四，仍同云姜、纫兰、素安、金夫人、徐夫人过枣花寺看牡丹，因前日风雨、花已零落殆尽。","f":"七言律诗","c":["扶头雾雨催春尽。","十日旧游花尚嫩。","东风一夜损芳菲，满地落红深几寸。","风前弱絮吹成阵。","栏外绿阴经雨润。","回头一笑嘱花王，来岁花开仍过问。"]},{"t":"金缕曲 红拂","f":"古风","c":["世事多奇遇。","快人心、天人合发，英雄侠女。","阅世竟无如公者，决定终身出处。","特特问、君家寓所。","逆旅相依堪寄托，好夫妻、端合黄金铸。","女萝草，附松树。","尸居余气何须惧。","问隋家、驱鱼祭獭，为谁辛苦。","况是荒荒天下乱，仙李盘根结固。","更无奈、杨花自舞。","悔不当初从嫁与，岂留连、一妓凭君取。","远人也，越公素。"]},{"t":"金缕曲 红线","f":"古风","c":["技也原非幻。","入危邦、床头盗合，身轻如燕。","甲帐风生申夜警，悄过兰堂深院。","好趁取、灯昏香断。","太乙神名书粉额，挂胸前、匕首龙纹灿。","奇女子，字红线。","功成岂为求人见。","慰君忧、感知酬德，免他争战。","遁迹云山游世外，酒海花场谁恋。","劳主帅、中庭夜饯。","野鹤翩然随所适，冷朝阳、特赋菱歌怨。","乘雾去，碧天远。"]},{"t":"金缕曲 红绡","f":"古风","c":["赫赫威权者。","锁金闺、名姝十院，花台月榭。","何必绯桃延佳士，此是君侯自惹。","又何必、乌龙守夜。","一面菱花云记取，好良期、三五清辉射。","花阴底，月光下。","潭潭院宇人皆怕。","越重垣、金釭半敛，云鬟初卸。","空倚玉箫愁不尽，蓦地人来迎迓。","问何术、仙乎神也。","磨勒奇谋人不识，莽昆仑、能使红绡嫁。","百年偶，本无价。"]},{"t":"台城路 四月廿四城东泛舟","f":"古风","c":["清溪一带城东路，新蜩乍鸣高柳。","五里蒹葭，数声啼鸟，正是薰风时候。","将船载酒。","感卅载重来，光阴回首。","蟹罟鱼罾，小楼临水尚依旧。","天光水影荡漾，看翩翩巧燕，波面飞逗。","绿树成阴，红栏倒影，野色暗侵襟袖。","维舟渡口。","听萧寺钟声，梵宫轻扣。","留客殷勤，再来秋雨后。"]},{"t":"八归 题张雪鸿秋荷双鸳","f":"古风","c":["雪泥鸿爪，文章游戏，只不过偶然耳。","红衣坠露无多少，画出半秋天气，双鸳相倚。","岸草汀花残照外，对渺渺、冷烟寒水。","已看到、寥落西风，又吹过沙尾。","睡去。","迷离短梦，缠绵情绪，结伴荷花莲子。","忘机淡宕，逍遥野浦，不与世间闲事。","甚风流活计，装点溪山被纹绮。","好意态、金针谁绣，老笔同题，消遣绿窗里。"]},{"t":"贺新凉 康介眉夫人嘱题榕阴消夏图","f":"古风","c":["深院闲池馆。","此神仙、清凉世界，热红尘远。","午倦停针消长昼，榕叶婆娑影转。","正茉莉、蛮花香散。","花底翩翩瑶台侣，羡连枝、玉树人清婉。","联好句，写双管。","鲛绡衣薄轻罗扇。","拥金盘、荔支熟矣，槟榔初荐。","一幅新图传陈事，历历红栏碧藓。","好随载、镜奁书案。","粤峤珠江当年景，寄都门、女伴题诗满。","惜末识，画中面。"]},{"t":"山亭宴 立秋","f":"古风","c":["井梧一叶银床早。","碧云天、画楼秋到。","竹外淡烟霏，障满地、斜阳最好。","豆花凉蔓战西风，浑不似、春寒料峭。","高树晚蝉呜，时诉出、凄凉调。","荷花半倚闲池沼。","想岩壑、桂花香渺。","天意谢繁华，怕白露、暗催秋老。","罗衾不奈乍凉宵，有花底、乱虫啼晓。","清梦醒来时，一点残灯袅。"]},{"t":"定风波 谢云姜妹赠蜜渍荔支有感","f":"古风","c":["冰雪肌肤裹绛纱。","者般滋味产天涯。","二十七年风景变。","曾见。","连林闽海野人家。","何必更求三百颗。","珍果。","数枚直比服丹砂。","恰好嫩凉秋雨后。","消受。","感君高义转咨嗟。"]},{"t":"浣溪沙 夜坐","f":"七言古诗","c":["竹影朦胧树影长。","轻烟黯淡月昏黄。","喓喓秋院乱啼螀。","几点微芒萤火细，一天风露豆花凉。","夜深鼯鼵上宫墙。"]},{"t":"百字令 题李升金璧二十四化长卷","f":"古风","c":["晚来恃好，映斜阳、二十四峰交错。","依约红墙林外寺，楼阁参差飞舞。","渔笛吹残，雁行初起，野艇冲烟渡。","澄波如练，落霞远趁孤骛。","楚楚。","返照晴岚，涂金刷翠，极目山无数。","浓抹淡妆秋万里，冷到江头枫树。","江水长流，碧山无恙，阅尽狂今古。","锦奴名字，千年片纸留住。"]},{"t":"金缕曲 题刘季湘夫人《海棠巢乐府》孙平叔总制室","f":"古风","c":["小雅离骚旨。","好文章、半生事业，千秋名字。","叠雪裁冰词绝妙，不共吹花嚼蕊。","早称出、拖金衣紫。","天际灵风飘玉叶，海棠巢、万点胭脂醉。","三复读，羡无已。","一输明月前身是。","迥超尘、海镜流球，寒芒万里。","羞煞凡间儿女语，锦瑟朱弦清丽。","使听者、洋洋盈耳。","肃肃雍雍廊庙器，岂寻常、粉黛娇容止。","想老笔，更精粹。"]},{"t":"钗头凤 秋海棠","f":"古风","c":["清清露。","涓涓注。","嫩红细点黄心吐。","花如泪。","叶如翠。","花花叶叶，一般酸味。","记。","记。","记。","虫声诉。","西风妒。","秋来更向谁分付。","闲愁积。","人不寐。","半规残月，凉生绣被。","睡。","睡。","睡。"]},{"t":"秋风第一枝 桂","f":"古风","c":["碧丛丛、金粟飘香。","乍染衣裾，风露生凉。","蟾影三更，广寒万里，谁酌天浆。","秋将半、丹砂细量。","夜深沈、仙姝淡妆。","听彻清商。","罗幛云屏，梦也难忘。"]},{"t":"蝶恋花 黄葵","f":"古风","c":["小院钩帘人睡醒。","曲角栏干，移过重重影。","似水天光云叶净。","微凉略觉风儿劲。","不卷轻罗花态胜。","慢卷轻罗，一片斜阳冷。","浅淡衣裳妆束靓。","比肩惟许芙蓉并。"]},{"t":"凌波曲 枸杞","f":"古风","c":["深丛浅丛。","天高露浓。","仙人杖引灵风。","挂星星碎红。","花砖细封。","苍苔细茸。","狸奴巧俟游蜂。","费丹青画工。"]},{"t":"太常引 玉簪","f":"古风","c":["凉生花径报新秋。","粉墙下、几枝抽。","白玉琢搔头。","禁不住、西风暗飕。","碧云院宇，碧纱窗户，碧水更清柔。","斜日过妆楼。","早又是、珠帘上钩。"]},{"t":"浪淘沙","f":"古风","c":["楼外雨初晴。","人倚云屏。","月华如水照吹笙。","多事夜寒添半臂，春也无情。","残烛尚荧荧。","好梦初惊。","纱窗晓色已平明。","天籁不知何处寺，一片虚灵。"]},{"t":"尾犯 九月五日雨中作","f":"古风","c":["风雨近重阳，香噀短篱，秋水清洁。","落帽题糕，费词人饶舌。","天将晚、潇潇雨意，酒初醒、沈沈妆阁。","听疏帘外，一阵西风，触动橹铃铁。","残虫声渐歇。","况又到、霜冷时节。","多病年来，怕镜中消削。","爱红叶、碧山谁染，剪黄花、翠襟自襭。","登高心兴，似比著、当年更薄。"]},{"t":"一剪梅 雨中剪菊花赠纫兰妹","f":"古风","c":["暮秋天气太无聊。","风又凄凄，雨又潇潇。","清樽共酌恨难招。","一道重城，千里之遥。","东篱乍满冷香飘。","次第开来，昨日今朝。","露黄亲剪好丰标。","满贮筠篮，玉蕊金苞。"]},{"t":"被花恼 题王石谷画友梅轩图","f":"古风","c":["疏枝老干自斜横，开满冷花冰蕊。","竹里柴门对流水。","夜深人静，梦回酒醒，半隐鸟皮几。","明月下，小窗前，乱飞琼雪寒烟里。","潇洒足平生，不作劳劳羁宦子。","梅花结伴，修竹苍松，乐事无过此。","任三春桃李斗芳菲，怕风动、娇红尽吹起。","画图上，一片清香生素纸。"]},{"t":"点绛唇 题朱葆瑜女史锄月种梅图","f":"古风","c":["月满风清，晴香乍试花心净。","荷锄幽径，疏密安排定。","花压栏干，翠袖和香凭。","天如镜。","横斜掩映。","有个人相称。"]},{"t":"白蘋香 赠闻诗室女士钱叔琬，于万秀才令妹","f":"古风","c":["见面浑如旧识，知名久矣初逢。","一湖秋水簇芙蓉。","玉树幽兰相共。","蔼蔼温柔笑语，雍雍林下家风。","闻诗闻礼宛从容。","万里桐花雏凤。"]},{"t":"烛影摇红 听梨园太监陈进朝弹琴","f":"古风","c":["雪意沈沈，北风冷触庭前竹。","白头阿监抱琴来，未语眉先蹙。","弹遍瑶池旧曲，韵泠泠、水流云瀑。","人间天上，四十年来，伤心惨目。","尚记当初，梨园无数名花簇。","笙歌缥缈碧云间，享尽神仙福。","叹息而今老仆。","受君恩、沾些微禄。","不堪回首，暮景萧条，穷途哀哭。"]},{"t":"木兰花慢 瓶花论，效刘克庄体","f":"古风","c":["瓶花千百样，要好是、在人为。","或冷淡相兼，疏疏密密，转侧相宜。","或苍秀艳丽者，似洞天幽谷态离奇。","或是粗枝大叶，恍然羽葆云旗。","铜觚瓦瓮右军持。","风月好良期。","绝妙处微微，半窗月影，荡荡风丝。","不同丁香结子，也不同红豆寄相思。","那怕游蜂细蝶，任他青女封姨。"]},{"t":"步蟾宫 至日","f":"七言律诗","c":["黄钟律吕吹葭管。","浙风日、阳和向暖。","诗书相对坐晴窗，看野马、纷纷过眼。","五纹谁计丝长短。","且图个、画长一线。","自知不共世人妆，何必问、画眉深浅。"]},{"t":"惜分钗 看童子抖空冲","f":"古风","c":["春将至。","晴天气。","消闲坐看儿童戏。","借天风。","鼓其中。","结彩为绳，截竹为筒。","空。","空。","人间事。","观愚智。","大都制器存深意。","理无穷。","事无终。","实则能鸣，虚则能容。","冲。","冲。"]},{"t":"一丛花 题云林《福连室吟草》","f":"古风","c":["连枝玉树羡君家。","天与好才华。","知名彼此情先熟，恨万重、水障云遮。","今始见君，神情散朗，清洁比梅花。","新诗示我妙无加。","词调更堪夸。","丹青更有生花笔，写湖山、翠霭朱霞。","咳唾成珠，池塘结梦，春草遍天涯。"]},{"t":"思佳客 腊九日，同云林、云姜、纫兰、佩吉集于珊枝斋中，时云姜行有日矣，佩吉鼓《阳关三叠》，尽一日欢。归途城门将阖，车中口占","f":"古风","c":["三叠阳关不忍听。","七条弦上半离声。","浇愁且尽杯中物，日暮君归我进城。","弦月上，影悬冰。","凉风吹面酒初醒。","明灯小队遵归路，寒柝沿街已定更。"]},{"t":"定风波 同诸姊妹听佩吉弹《平沙落雁》一曲，并见赠花卉四帧，词以谢之","f":"古风","c":["一曲瑶琴为我弹。","北风烈烈指头寒。","想见秋江残照里。","烟水。","联翩雁影下空滩。","赠我新图花似锦。","能品。","朱藤黄菊耐人看。","少长咸集邀女伴。","也算。","瑶池小宴会神仙。"]},{"t":"唐多令 谢云林见赠古玉琴帚，且邀明日赏雪。用谢蜜来韵","f":"古风","c":["常伴镜奁边。","常随碡瑁筵。","费仙人、种玉生烟。","扫尽纤尘弹一曲，明月下、百花前。","笑我近来颠。","邀君雪后天。","喜同心、兰蕙斯言。","愿得一生长聚首，丝竹事、乐中年。"]},{"t":"飞雪满群山 十五雪后，同诸姊妹天宁寺看唐花，望西山积雪分韵","f":"古风","c":["银海摇光，玉山霏素，平临万井烟村。","嫩杨枝上，青帘高挂，飞来一缕春痕。","妙香生佛字，恍行入、桃源洞门。","花光照眼，花香染袖，花底醉游人。","禅院里、同登欢喜地，倚明窗西望，笑语欣欣。","云笺佳句，朱弦法曲，何殊桃李春园。","良辰容易过，且消受、香温酒温。","夕阳才没，半城凉月天未昏。"]},{"t":"满庭芳 瘗鬟铭","f":"古风","c":["璧月常亏，彩云易散，惜哉况我痴情。","天乎何意，尤物太精灵。","犹记憨憨样子，尚依稀、耳畔金铃。","妆台侧，衔脂弄粉，难忘小芳名。","罡风。","吹短劫，优昙才见，一霎飘零。","费主人老泪，啼雨难晴。","怕向垂杨楼下，伤心处、芳草青青。","栏干角，一抔黄土，记取瘗鬟铭。"]},{"t":"鹧鸪天 元日咏荠菜，用去年荠菜韵","f":"古风","c":["鲜荠登盘乍吐花。","嫩苗争长傲春奢。","已知草色迎年绿，略有新黄发柳芽。","山之罅，水之涯。","风丝日影暖相加。","岁朝图上应添写，小白微青最可夸。"]},{"t":"玉连环影 元日解九连环","f":"古风","c":["连络，个个环相约。","解得开时，本自无缠缚。","系连环，解连环，一笑人间万事理皆然。"]},{"t":"琴调相思引 题百福老人蓝笔画兰","f":"古风","c":["同心芳草淡青钩。","艳过春花冷过秋。","翰林学士，画意本清幽。","神品倩人题好句，生绡尚有暗香留。","老人名字，千古足风流。"]},{"t":"满江红 人日观音院饯云姜南归","f":"楚辞体","c":["归去来兮，怕君去、少留君坐。","说不尽、离愁彼此，泪随声堕。","野店长途当自爱，脂车秣马须亲课。","报平安、两字寄书频，君休惰。","新年事，匆匆过。","冰初解，东风大。","隔江关千里，相思无那。","今日分襟何日见，观音不管人些个。","听一声、珍重去难留，伤心我。"]},{"t":"风入松 春灯次夫子韵二首 其一","f":"古风","c":["沿河新草绿堪挑。","丝柳渐开条。","六鳌海上凌风至，献明珠、火树蟠桃。","十里朱阑画阁，满天月壁星轺。","太平乐事庆清朝。","结伴走天桥。","钿车游马笙歌队，望青帘、春酒新烧。","红烛缘街引路，浮圆到处元宵。"]},{"t":"风入松 春灯次夫子韵二首 其二","f":"古风","c":["华堂春暖设春筵。","灯彩月华天。","上元南极开芳宴，宴群仙、香袅云盘。","彩服庭前儿女，貂裘门下衣冠。","春王宝箓注延年。","松柏荫常圆。","喜君与我生同岁，祝三多、乐胜从前。","好景何如今夕，新诗载入芸编。"]},{"t":"醉红妆 自题海棠摺扇，赠云林","f":"古风","c":["薄寒轻暖近清明。","试新妆，出华清。","宿酲未解尚懵腾。","娇无那，画栏凭。","碎红滴露染猩猩。","烧绛烛，照娉婷。","须知画意即诗情，三五朵，一枝横。"]},{"t":"鹊桥仙 云林瞩题闰七夕联吟图","f":"古风","c":["新秋逢闰，鹊桥重驾，两度人间乞巧。","参横月转玉绳低，问乞得、天机多少。","闺中女伴，天边佳会，多事纷纷祈祷。","总然天上有神仙，怕也共、有情天老。"]},{"t":"浪淘沙 正月廿七闻雁忆云姜","f":"古风","c":["别后数征邮。","应到扬州。","相思一日似三秋。","恼煞雁行天上字，字字离愁。","回首忆春游。","花底句留。","三分春又一分休。","屈指海棠开日近，不见归舟。"]},{"t":"金缕曲 自题听雪小照","f":"古风","c":["兀对残灯读。","听窗前、萧萧一片，寒声敲竹。","坐到夜深风更紧，壁暗灯花如菽。","觉翠袖、衣单生粟。","自起钩帘看夜色，厌梅梢、万点临流玉。","飞霰急，响高屋。","乱云堆絮迷空谷。","入苍茫、冰花冷蕊，不分林麓。","多少诗情频到耳，花气薰人芬馥。","特写入、生绡横幅。","岂为平生偏爱雪，为人间、留取真眉目。","栏干曲，立幽独。"]},{"t":"一剪梅 闻云姜渡河信","f":"古风","c":["闻道行程已渡黄。","江北淮南，云树苍茫。","锦书春信远相将。","嗟我怀人，实彼周行。","两岸青山客梦长。","千里之思，一日难忘。","绿杨城郭近雷塘。","所谓伊人，在水一方。"]},{"t":"杏花天 同游南谷，云林妹先返，怅然赋此","f":"古风","c":["倚楼目送人归去。","望不尽、杏花深处。","香车转过山前路。","苦被垂杨遮住。","方七日、唱予和汝。","匆匆返、去而不顾。","虽云小别愁难诉。","彼此相思情互。"]},{"t":"乳燕飞 挽许金桥侄，呈珊枝嫂","f":"古风","c":["日暮忽闻讣。","蓦传来、金桥厌世，痛心惊仆。","三日云何成长往，莫是庸医耽误。","廿八岁、摧残玉树。","母老家贫情特惨，况安人、年少娇儿孺。","伤心事，竟难诉。","箪瓢陋巷安其素。","最难忘、音容笑貌，翩翩风度。","断简残篇零落散，渺渺钱塘归路。","何日葬、半山坟墓。","哭不成声心已醉，挽斯人、未尽斯人苦。","权当作，招魂赋。"]},{"t":"如梦令 送春","f":"古风","c":["昨日送春归了，枝上残红渐少。","帘外绿阴多，满地落花谁扫。","休扫，休扫，一任东风吹老。"]},{"t":"伊州三台 题云林扇头弹琴仕女","f":"古风","c":["西风吹入梧桐。","半卷珠帘露浓。","独坐月明中。","正闲阶、几声暗虫。","人间天上情踪。","泛以冰丝细通。","一曲特愁侬。","态憨憨、似终未终。"]},{"t":"探春慢 题顾螺峰女史 韶 画寻梅仕女，用张玉田韵","f":"古风","c":["寒浦藏烟，小桥堆絮，人与花分清淡。","竹压低梢，松培老干，簌簌琼英霏霰。","才试着花气，早望见、朱栏一半。","若非群玉山头，月明林下香散。","可是汉家宫苑。","又不似唐昌，树底忽见。","黄鹤楼中，玉门关外，休付笛声吹怨。","留待东风至，却还怕、绿阴争暖。","笑捻花枝，归来香满庭院。"]},{"t":"浣溪沙 谢云林妹见赠自画樱笋团扇","f":"七言古诗","c":["芍药将开卸海棠。","最怜樱笋好年光。","落花庭院绿阴长。","写就新图颜色嫩，书成小令墨痕香。","也凭红翠竞春芳。"]},{"t":"江城子 题孙子勤西溪纪游图","f":"古风","c":["西溪溪水拍长天。","放游船。","足留连。","一片芦梢飞雪满前滩。","仙侣同舟归去晚，夕阳下，起寒烟。","乘流欲上白云间。","小桥边。","浪花圆。","只有忘机鸥鹭对人闲。","回首茅庵红叶里，僧遥客，倚栏干。"]},{"t":"菩萨蛮 端午日咏盆中菊","f":"古风","c":["薰风殿阁樱桃节。","碧纱窗下沈擅爇。","小扇引微凉。","悠悠夏日长。","野人知趣甚。","不作炎凉问。","老圃好栽培。","菊花五月开。"]},{"t":"栏千万里心 听雨忆云林","f":"楚辞体","c":["窗前新种绿芭蕉。","夜雨声声枕上敲。","困不处眠转寂寥。","耐清宵。","有美人兮不可招。"]},{"t":"琴调相思引 云林妹见赠雁足书灯，以小令申谢","f":"古风","c":["雁字分飞思不禁。","听风听雨梦难寻。","露华庭院，灯影照清心。","赠我不须长夜饮，感君聊赋短檠吟。","荧荧一点，应惜寸光阴。"]},{"t":"鹊桥仙","f":"古风","c":["琅玕一径，瑶琴三弄，人在清凉极处。","萧萧疑雨又疑风，倚怪石、苍苔珠树。","云中仙鹤，花间雏凤，万里丹山平步。","更邀明月照幽篁，消受这、满身香雾。"]},{"t":"贺新凉 夏日余季瑛招饮绿净山房作","f":"古风","c":["小宴神仙宅。","坐苍茫、回廊曲折，高槐如幄。","海上荔支枝头杏，玉斗香斟云液。","爱雪藕、冰盘清洁。","卜筑山房成大隐，羡主人、潇洒能留客。","尽一日，花间酌。","地偏心远无尘迹。","倒清樽、群贤咸集，骋怀游目。","西下夕阳云乍起，一霎电雷交作。","风过处、新凉如沐。","雨后沿阶芳草色，映冰绡雾縠衣裳碧。","归未晚，不须烛。"]},{"t":"意难忘 自题梅竹双清图","f":"古风","c":["一径幽香。","傍猗猗修竹，疏影扶将。","横斜深院宇，冷艳小池塘。","才雪后，乍芬芳。","尽无语持觞。","向夜阑、巡檐索句，特费思量。","相思难话衷肠。","想佳人空谷，一样情伤。","帘栊灯黯淡，篱落月昏黄。","多少事，意难忘。","似不自禁当。","更怕他、新愁旧梦，虚度年光。"]},{"t":"碧芙蓉 雨后由三官殿同云林、纫兰过尺五庄看荷花作","f":"古风","c":["一带小红桥，同倚画栏，池面荷靓。","飐飐芦梢，立蜻蜓不定。","新雨过、琼珠万点，荡流霞、妙莲香冷。","听垂杨岸，几树鸣蝉，催起游人兴。","虚亭萦曲沼，望不尽、绿叶千柄。","隔水盈盈，似美人临镜。","雪冰藕、凉生罗袂，泛清樽、风吹酒醒。","断云残照，渐花外、天光向瞑。"]},{"t":"南柯子 咏香串效唐人体","f":"古风","c":["宝串垂襟软，温香著体柔。","青丝贯取意绸缪。","只要心心相应、总无愁。","步月难寻梦，临风怕倚楼。","江皋玉佩为谁留。","又惹一番牵挂、在心头。"]},{"t":"浪淘沙 送珊枝归武林","f":"古风","c":["归计太匆匆。","难写离衷。","孤帆双桨趁秋风。","肠断天涯从此去，甚日重逢。","相别各西东。","浪迹萍踪。","怜君多病况龙钟。","一纸青书劳怅望，须付征鸿。"]},{"t":"伊州三台 七夕夜雨，次日立秋戏题","f":"古风","c":["秋声先到芭蕉。","阶下秋虫絮叨。","生受鹊填桥。","渡银河、夜凉路遥。","洗车丝雨飘萧。","冷落星娥翠翘。","云气湿轻绡。","愿来年、莫同这遭。"]},{"t":"迷神引 题徐廷昆画","f":"古风","c":["叠叠银涛翻雪浪。","黯黯冷云飞涨。","垂藤古木，石壁高无量。","望蓬莱，三山远，长风荡。","日月双丸小，来复往。","天地渺无涯，窈空旷。","忽有仙舟，一叶乘波放。","看鬓眉纤，霞裾敞。","满盘花果，玉瓶贮，蒲桃酿。","是广寒宫，霓裳舞，月中样。","白兔守筠笼，随竹舫。","猿子采蟠桃，亲呈上。"]},{"t":"江城梅花引 雨中接云姜信","f":"古风","c":["故人千里寄书来。","快些开。","慢些开。","不知书中，安否费疑猜。","别后炎凉时序改，江南北，动离愁，自徘徊。","徘徊。","徘徊。","渺予怀。","天一涯。","水一涯。","梦也梦也，梦不见、当日裙钗。","谁念碧云，凝伫费肠回。","明岁君归重见我，应不似，别离时，旧形骸。"]},{"t":"步虚词 中秋","f":"古风","c":["玉剪燕归秋社，木犀香浸云屏。","连阴初霁月华清。","恼煞碧天风劲。","细露凉生池阁，流云暗度瑶京。","羽衣纤指学吹笙。","不许人间偷听。"]},{"t":"燕归梁 自题画杏","f":"古风","c":["得意东风快马蹄。","细草沙堤。","几枝丰艳照清溪。","垂杨外，小桥西。","写来还恐神难似，肥和瘦。","要相宜。","碧纱窗下倩君题。","聊记取、旧游时。"]},{"t":"风入松 题王叔明听松图","f":"古风","c":["乱山深处有人家。","细路欹斜。","长松万树围茅屋，响寒涛、天际青霞。","曲涧平铺略约，飞泉高挂檐牙。","幽人肥遁厌烦哗。","云水生涯。","携筇来有谈经客，露疏窗、萝薜周遮。","陋室居之何陋，满堂金玉无加。"]},{"t":"凌波曲 孙媖如女士嘱题吹笛仕女团扇","f":"古风","c":["西风露零。","高楼笛声。","无端吹起离情。","落梧桐叶轻。","三更四更。","云窗未扃。","小蟾斜影分明。","挂栏干正平。"]},{"t":"东风齐著力 水波，得平字","f":"古风","c":["燕子来时，回塘向暖，野水烟生。","刚胜弱絮，初泛落花轻。","漫漫垂杨曲沼，才添了、几点浮萍。","鱼苗长，生机浩荡，恰趁新晴。","雾縠太轻盈。","波细细、参差碧浪纵横。","遥天倒影，渺渺动柔清。","好是东风消息，吹不定、似皱还平。","天涯路，一篙新涨，万里春程。"]},{"t":"广寒秋 九月十九过天仙庵，同福真老尼茶话","f":"古风","c":["禅房寂静，苍苔浓厚，冷淡斜阳阴里。","去年曾到又重来，正幽径、黄花开矣。","冷风轻扬，旃檀香霭，悦可众心欢喜。","一杯清茗话西窗，渐薄暮、钟声初起。"]},{"t":"金缕曲 送纫兰妹往大梁","f":"古风","c":["三载交情重。","竟难留、买舟南去，北风初动。","行李萧萧天气冷，落叶黄花相送。","正河水、冰澌将冻。","满载异书千万卷，有斯冰、小印随妆笼。","千里路，全家共。","年来送客愁相踵。","要相逢、都门汴水，与君同梦。","此后平安书屡寄，慰我愁怀种种。","洒清泪、离觞互捧。","聚散本来无定数，古阳关、不忍当筵弄。","金缕曲，为君诵。"]},{"t":"传言玉女 雪夜不寐","f":"古风","c":["一夜风威，灯晕疏窗微照。","云母屏风，护罗帏寒峭。","黄花影里，数尽更筹多少。","新愁旧闷，竟难忘了。","多病何堪，纷绪乱萦怀抱。","茶铛药裹，扬轻烟香杳。","棱棱瘦骨，顾影翻然成笑。","游仙有梦，也成颠倒。"]},{"t":"浣溪沙 游仙体，用“遥知杨柳是门处，似隔芙蓉无路通”，成此小令二阕 其一","f":"七言古诗","c":["碧落茫茫秋水斜。","朱门深被绿杨遮。","隔溪听尽晚蝉哗。","无可奈何人怅望，难通消息树交加。","能忘情者是仙家。"]},{"t":"浣溪沙 游仙体，用“遥知杨柳是门处，似隔芙蓉无路通”，成此小令二阕 其二","f":"七言古诗","c":["开遍芙蓉叶叶凉。","天成锦障护池搪。","伊人宛在水中央。","十二栏干人不见，三千世界路何长。","空教秋雨洗红妆。"]},{"t":"祝英台近 柘龙潭，用吴梦窗韵","f":"古风","c":["古松阴，幽涧底，流水漱山股。","红叶寒烟，飞鸟自来去。","苍茫草界羊踪，霜封樵径，石头滑、舆夫相语。","酌清俎。","穿林瑟瑟风吹，阴崖望堆素。","缥缈峰头，指点过来路。","平临佛刹巍峨，钟声初起，梵音散、诸天花雨。"]},{"t":"菩萨蛮 西观音洞","f":"古风","c":["朝阳初上岩头树。","清晨步入蚕丛路。","云隐小红墙。","钟声发上方。","高碑书故事。","苔藓侵碑字。","大士坐莲台。","莲花何处开。"]},{"t":"菩萨蛮 东观音洞","f":"古风","c":["斜肠乍转夕阴结。","观音古洞寒泉冽。","黄叶拥禅关。","山僧终日闲。","石桥通曲径。","树杪栖乌定。","修竹暗森森。","悠然净客心。"]},{"t":"菩萨蛮 西峰寺","f":"古风","c":["罗喉岭下苍烟织。","乱云深谷披荆棘。","红叶被山阿。","寒林废塔多。","寺门残照里。","古洞余荒址。","殿角秀长春。","花开日日新。"]},{"t":"菩萨蛮 登石景山天空寺望浑河","f":"古风","c":["浑河东岸孤峰起。","崔巍绝顶浮图峙。","陡辟四天门。","天空只树园。","登高同策马。","陟彼寻兰若。","竞渡俯长桥。","霜华晓未消。"]},{"t":"广寒秋 题慈相上人竹林晏坐小照","f":"古风","c":["琅玕阴里，是心清净，晏坐了无余说。","岩花涧草任风吹，更不许、纷纷饶舌。","西方何处，长安道远，且向这边休歇。","扫除一切性光圆，本来法、无生无灭。"]},{"t":"浪淘沙慢 久不接云姜信，用柳耆卿韵","f":"古风","c":["又盼到、冬深不见，故人消息。","况当雪后，几枝寒梅，绿萼如滴。","对暗香疏影思佳客。","细思量、两地相思，怕梦里、行踪无准，各自都成悲戚。","无极。","九回柔肠，十分幽怨，几度写付宫阕，鸿雁空延伫，虽暂成小别，也劳心力。","回首当初，在众香国里花同惜。","恁无端、寒来暑往，天天使人疏隔。","知何时、共剪西窗烛，万千言与语，叨叨向说。","却还愁，说不尽、从前相忆。"]},{"t":"一丛花 题湘佩《鸿雪楼词选》","f":"古风","c":["雪泥鸿爪旧游踪。","南北任飘蓬。","花帘昔有吟诗侣，喜天游、邂逅初逢。","彩笔一支，新诗千首，名重浙西东。","哀而不怨宛从容。","珠玉粲玲珑。","鸳鸯绣了从君看，度金针、灭尽裁缝。","大块文章，清奇格调，不减古人风。"]},{"t":"蟾宫曲 立春","f":"古风","c":["畅晴和、好是今朝。","律转青阳，冶叶昌条。","暖入屠苏，宜春剪字，彩胜云翘。","碧琉璃、房拢日高。","绣帘儿、东风细飘。","腊雪全消。","春到人间，柳宠花矫。"]},{"t":"伊州三台 猗兰曲","f":"楚辞体","c":["兰兮生自空山。","流出幽香世间。","清露润芳颜。","托离骚、美人意传。","休夸雾鬓烟鬟。","不与群花并看。","描写入冰弦。","数芬芳、算伊占先。"]},{"t":"醉太平 题蓉桂双白头图","f":"古风","c":["金风素秋。","露华暗浮。","天光夜色幽幽。","挂凉蟾一钩。","芙蓉太柔。","木犀更幽。","白头同宿枝头。","笑鸳鸯逐流。"]},{"t":"风光好 春日","f":"古风","c":["好时光。","渐天长。","正月游蜂出蜜房。","为人忙。","探春最是沿河好。","烟丝袅。","谁把柔条染嫩黄。","大文章。"]},{"t":"浪淘沙 登香山望昆明湖","f":"古风","c":["碧瓦指离宫。","楼阁飞崇。","遥看草色有无中。","最是一年春好处，烟柳空濛。","湖水自流东。","桥影垂虹。","三山秀气为谁钟。","武帝旌旗都不见，盛世难逢。"]},{"t":"貂裘换酒 题扇头“鸡声茅店月，人迹板桥霜”画意","f":"古风","c":["飒飒西风冷。","挂林稍、微茫淡月，碧空澄净。","己被鸡声催人起，落落溪桥幽径。","舞黄叶、随风不定。","店舍无烟关山远，渐轮蹄、惊动栖乌醒。","襟袖裂，晓塞劲。","新霜路滑鞭敲镫。","板桥头、萧萧寒溜，明星尚烱。","指点前村依稀见，野火孤灯相映。","望不尽、鱼天耿耿。","一片朝霞烘远树，涌红暾、宿草霜华净。","云断处，误山影。"]},{"t":"寿楼春 送春","f":"古风","c":["吁嗟乎春归。","奈匆匆不住，轻送芳菲。","几处园林池馆，落红霏霏。","无意绪，裁春衣。","想去年、百花开时。","记剪烛山楼，看花古寺，回首梦依稀。","谁能禁，东风吹。","倚栏干几曲，心与时违。","又是杨花糁径，海棠垂丝。","春已去，人如斯。","更那堪、幽思空悲。","对芳草深庭，帘拢未垂双燕飞。"]},{"t":"定风波 雨中海棠","f":"古风","c":["晓起庭除遍落花。","乱红和雨受风斜。","惟许荼蘼同一梦。","寒重。","飘零残粉卸韶华。","满树轻阴垂绿绶。","剩有。","翩翩碎影护檐牙。","切莫东风尽吹落。","斟酌。","枝头红萼暂留些。"]},{"t":"江城子 落花","f":"古风","c":["花开花落一年中。","惜残红，怨东风。","恼煞纷纷如雪扑帘栊。","坐对飞花花事了，春又去，太匆匆。","惜花有恨与谁同。","晓妆慵。","忒愁侬。","燕子来时红雨已濛濛。","尽有春愁衔不去，无端底，是游蜂。"]},{"t":"春去也 飞絮","f":"古风","c":["春去也，点点舞杨花。","落溷沾茵无定准，任教风送到天涯。","惆怅送年华。"]},{"t":"雪夜渔舟 题励宗万雪渡图","f":"古风","c":["朔风紧。","催雪满群山，六花成阵。","水面凝烟，芦稍戛玉，败叶乱随风陨。","溪山妆粉。","掩映出、短篱疏影。","树鸦惊起，弥漫村舍，板桥难认。","冻云飞不尽。","望长空一色，水天深隐。","唤渡纷纷，披蓑戴笠，银海冷光生晕。","去程远近。","好趁取、晚来风顺。","兰桡桂桨，空明击溯，画图诗境。"]},{"t":"并蒂芙蓉 题蒋南沙相国画并蒂莲花","f":"古风","c":["水净风疏，照碧天倒影，花间无暑。","清露洗红妆，爱金蕊交错。","同心并头两朵，洛浦凌波笑相与。","结成伴侣，惜双双、占断风流娇妩。","渺渺曲塘落日，问何来小鸟，双栖双伫。","不肯画鸳鸯，怕花里耽误。","莲花自然洁净，那管根芽淤泥污。","这般态度。","愿生生、总开一处。"]},{"t":"丑奴儿","f":"古风","c":["虚心直节裁为桶，野卉奇葩。","排比杈枒。","离合神光灿若霞。","铜觚玉盎何须论，青绿交加。","缕篆雕花。","长短随心不及他。"]},{"t":"金缕曲 戏述懒","f":"古风","c":["晓起临妆懒。","觉年来、闲身多病，神思苦短。","谁耐宫鬟梳浮渲，管甚胭脂浓淡。","更谁问、画眉深浅。","辜负描花新样好，度金针、怕引丝丝线。","蔷薇露，不须盥。","研池积水生苔藓。","任窗前、花花叶叶，随风飘卷。","开卷难成终卷读，断阕无心重按。","又不是、春醪醉晚。","瘦比黄花慵似柳，绣罗襦、随意腰围缓。","懒之病，最难遣。"]},{"t":"金缕曲 芸台相国以宋本赵氏《金石录》嘱题","f":"古风","c":["日暮来青鸟。","启芸囊、纸光如砑，香云缥缈。","易安夫妻皆好古，夏鼎商彝细考。","聚绝世、人间奇宝。","太息兵荒零落散，剩残编、几卷当年稿。","前人物，后人保。","芸台相国亲搜校。","押红泥、重重小印，篇篇玉藻。","南渡君臣荒唐甚，谁写乱离怀抱。","抱遗憾、讹言颠倒。","赖有先生为昭雪，算生年、特记伊人老。","千古案，平翻了。"]},{"t":"惜花春起早 本意","f":"古风","c":["晓禽呜，透纱窗、黯黯淡淡花影。","小楼昨宵听尽夜雨，为著花事惊醒。","千红万紫，生怕他、随风不定。","便匆匆、自启绣帘看，寻遍芳径。","阶前细草濛茸，承宿露涓涓，香土微泞。","今番为花起早，更不惜、缕金鞋冷。","雕栏画槛，归去来、闲庭幽静。","卖花声、趁东风，恰恰催人临镜。"]},{"t":"爱月夜眠迟 本意","f":"古风","c":["树影朦胧，望小蟾乍涌，人立桐阴。","草根虫语，沾衣露下，双双睡稳胎禽。","芭蕉掩却红灯，天街夜色深沈。","又谁家、一声声，不住敲动寒砧。","当此月满风微，把冰丝再鼓，谱入瑶琴。","井栏杆外，闪闪不定，萤火几点难寻。","清辉暗转花稍，良宵一刻千金。","想嫦娥、也如我，爱月不顾更深。"]},{"t":"阳台路 赋得“手倦抛书午梦长”，效柳耆卿体，并次其韵","f":"古风","c":["未天晚。","耐困人昼永，诗书抛乱。","掩纱厨、隐几南窗，神逐水沉香远。","莲漏丁丁，一枕梦游，柳憨花暖。","曾经惯。","旧路儿、桃源前度人散。","怅望碧溪流水，好梦醒、难抬倦眼。","细思量处，又惹下、暗愁无限。","人何在、风裳水佩，剩有绿阴幽馆。","无端鸟语惊回，从何消遗。"]},{"t":"南乡子 云林嘱题薰笼美人图","f":"古风","c":["窗外雪昏昏。","人倚薰笼昼掩门。","寒恋重衾眠不起，氤氲。","一瓣心香谁与焚。","写出画中身。","浅黛愁含隔宿痕。","彷佛思量多少事，消魂。","何处行云梦不真。"]},{"t":"喝火令 己亥惊蛰后一日，雪中访云林，归途雪已深矣。遂拈小词，书于灯下","f":"古风","c":["久别情尤热，交深语更繁。","故人留我饮芳樽。","已到鸦栖时候，窗影渐黄昏。","拂面东风冷，漫天春雪翻。","醉归不怕闭城门。","一路琼瑶，一路没车痕。","一路远山近树，妆点玉乾坤。"]},{"t":"柳梢青 题寒月疏梅图","f":"古风","c":["老干横斜。","一枝初放，低护檐牙。","雪后黄昏，吹来何处，怨笛哀笳。","冰姿不共凡葩。","照流水、清心自夸。","冷淡花光，朦胧月影，深院谁家。"]},{"t":"西子妆 三月十三，邀余季瑛、吴孟芬、钱伯芳、陈素安诸姊妹小集红雨轩看海棠，用吴梦窗韵。","f":"古风","c":["风信几番，半春过了，绛雪吹成香雾。","待看草色入帘青，敞疏窗、小轩花坞。","东风慢舞。","更分付、留春且住。","愿年年，到花开时候，良朋如许。","休轻误。","有限韶华，不许匆匆去。","蓬门花径为君开，隔春阴、海棠盈树。","拈题索句。","莫辜负、阳春同赋。","最关心、万点禁风薯雨。"]},{"t":"南乡子 惜花词","f":"古风","c":["一夜妒花风。","吹过栏干第几重。","何事封姨情太薄，匆匆。","零落深丛与浅丛。","春冷逼房栊。","晓起开帘扫落红。","风势未停天又雨，濛濛。","乱卷飞花小院中。"]},{"t":"江神子 听项屏山姊 紃 弹琴。","f":"古风","c":["画堂春暖日光晴。","坐深庭。","泛瑶觥。","一曲仙音、许我醉中听。","虽是初逢如旧识，言不尽，话生平。","落花风度水云声。","韵泠泠。","特分明。","真个九皋、长唳近虚灵。","听到曲终人语静，霍然使，寸心清。"]},{"t":"沁园春 游常氏废园，用竹叶庵“游孔氏废园”韵","f":"古风","c":["触目荒凉，小立回廊，夕阳斜矬。","认画栋妆楼，红窗疏敞，长楸修竹，绿叶婆娑。","满地浓阴，一声啼鸟，乔木森森绕薜萝。","玲珑石，仿奇峰怪岫，几朵青螺。","风流此地经过。","剩玩月、荒台照素娥。","想当日繁华，如今休矣，一朝散尽，妙舞轻歌。","烛灺香消，光沈响绝，过客空增感慨多。","风来处，听檐铃敲动，犹似鸣珂。"]},{"t":"凄凉犯 咏残荷，用姜白石韵。社中课题","f":"古风","c":["斜阳巷陌。","西风起、池塘一带萧索。","露倚半垂，雨欺平倒，画栏斜角。","风情最恶。","更不奈凉蟾影薄。","况飞飞、社燕将归，鸿影度沙漠。","回忆情何限，隔叶传歌，对花行乐。","无端青女，暗行霜、舞衣催落。","苦意清心，尚留得余香细著。","待同听、剪烛西窗，订后约。"]},{"t":"金缕曲 题《桃园记传奇》","f":"古风","c":["细谱桃园记。","洒桃花、斑斑点点，染成红泪。","欲借东风吹不去，难寄相思两字。","遍十二、栏干空倚。","冰雪肌肤琼瑶想，引情丝、蹙损春山翠。","仙家事，也如此。","凌风待月因谁起。","总无非、心心相感，情情不已。","只为情深深如海，泛出慈航一苇。","渡仙女、仙郎双美。","记取盟言桃花下，问三生、石上谁安置。","合欢斝，莫辞醉。"]},{"t":"茶瓶儿 病中谢闺友赠茶","f":"古风","c":["病里闲愁如织。","落花残、小庭人寂。","倦梳慵裹浑无力。","恰寄到、雨前新叶。","慰消渴情何极。","泛清芬、者般颜色。","绿尘飞盏，碧香生颊。","风定处、竹垆烟直。"]},{"t":"水调歌头 中秋独酌，用东坡韵","f":"古风","c":["云净月如洗，风露湛青天。","不知今夕何夕，陈事忆当年。","多少销魂滋味，多少飘萍踪迹，顿觉此心寒。","何日卸尘鞅，肥遁水云间。","沃愁肠，凭浊酒，枕琴眠。","任他素魄，广寒清影缺还圆。","谁管秋虫春燕，毕竟人生如寄，各自得天全。","且尽杯中物，翘首对婵娟。"]},{"t":"金风玉露相逢曲 中秋后一日，同云林、湘佩、家霞仙雨中游八宝山，晚晴，次湘佩韵","f":"古风","c":["寒烟罥树，凉风吹面，云外尖峰屏列。","相期不负雨中游，恍若是、山阴冒雪。","危栏倚袖，遥天极目，一片秋光清绝。","敲诗把酒晚晴初，卧夕照、残碑断碣。"]},{"t":"高山流水 听琴。社中课题","f":"古风","c":["七条弦上写柔情。","一丝丝、弹动秋声。","风拍小帘栊，花阴恰有人听。","芭蕉影、隔住红灯。","分明是，流水高山绝调，戛玉敲冰。","更幽兰制佩，腕底散芳馨。","泠泠。","虚空度鸿雁，寒浦外、水净沙平。","何处怨苍梧，落叶舞遍风轻。","掩朱帷、拍缓弦停。","夜深也，还怕纤纤素指，错点明星。","默无言、恍若江上数峰青。"]},{"t":"风入松 买菊","f":"古风","c":["满城风雨近重阳。","昨夜见微霜。","含苞细认玲珑叶，问佳名、色色端相。","出水芙蓉玉扇，落红万点霓裳。","萧条古寺积寒芳。","不论价低昂。","买归自向疏篱种，伴园蔬、平占秋光。","或有白衣送酒，且拼一醉花傍。"]},{"t":"瑶华 代许滇生六兄题海棠庵填词图","f":"古风","c":["闲庭日暮。","绛雪霏香，绕海棠无数。","苔痕草色，自有个、人在花深深处。","故烧高烛，照春睡、乌阑亲谱。","衍波笺、斟酌宫商，付与双鬟低度。","红牙缓拍新声，正料峭微寒，花影当户。","搓酥滴粉，还又怕、帘外柳梢莺妒。","春阴乍满，却不是、听风听雨。","擅风流、小样迦陵，一缕茶烟轻护。"]},{"t":"唐多令 十月十日，屏山姊月下使苍头遥糠一袋以饲猪，遂成小令申谢","f":"古风","c":["风起又黄昏。","鸦栖静不喧。","拍幽窗、霜叶翻翻。","把卷挑灯人未睡，酌杯酒、悄无言。","明月满前轩。","天高夜色寒。","有苍头、待月敲门。","一袋糟糠情不浅，感君赠、养肥豚。"]},{"t":"踏莎行 梦。次屏山韵","f":"古风","c":["幻影浮泡，原无凭据。","个中变化纷如缕。","也生欢喜也生愁，其间似有通神处。","念切情真，千头万绪。","相逢未准飘然去。","轻如蝴蝶腻如云，寒衾不耐天明雨。"]},{"t":"踏莎行 恨。次屏山韵","f":"古风","c":["黛浅鬟松，欲消无价。","者般滋味因谁惹。","香销风静月明时，更添一倍新愁也。","拍遍栏干，立来花下。","怕春归去催花谢。","待安排处费安排，旁人错解成闲话。"]},{"t":"鹊桥仙 牵牛。社中课题","f":"古风","c":["丝丝柔蔓，层层密叶，绿锁柴门小院。","朦胧残月挂林稍，早已是、牵牛开满。","一天凉露，半篱疏影，缥缈银河斜转。","枉将名字列天星，任织女、相思不管。"]},{"t":"塞上秋 雁来红。社中课题","f":"古风","c":["恼人最是西风，断肠听尽归鸿。","谁把胭脂画工。","者般调弄，染成芳草娇红。"]},{"t":"踏莎行 老境","f":"古风","c":["老境蹉跎，寄情缃素。","闲身拌作书丛蠹。","年来多病故人疏，生涯赖有山中冤。","梦去嫞寻，曲成自愿。","睡壶击缺愁难赋。","敢将沦谪怨灵修，虚名蚤被文章误。"]},{"t":"黄鹤引 挽白云观主张坤鹤老人","f":"古风","c":["寥天宗洞。","鹤驾云軿众仙拱。","五千文字功夫，玄珠流动。","凝神接踵。","不比寻常铅汞。","七十年，算是游戏人间一梦。","从此谢几尘，大药存真种。","炼成冰雪肌肤，驯龙调凤。","道高德重。","宝箓丹书亲奉。","一朝归去，御万里、长风相送。"]},{"t":"玉烛新 咏白海棠，用周清真韵。社中课题","f":"古风","c":["初晴新雨后。","乍洗褪胭脂，缟衣妆就。","东风倦倚，憨憨态、不管敲残更漏。","嫩寒天气，正睡稳、乌衣时候。","深夜静、银烛高烧，微香暗侵襟袖。","盈盈一点芳心，占多少春光，问卿知否。","红妆莫斗。","谁得似、净骨天然清瘦。","神娟韵秀。","雅称个、花仙为首。","还要倩、流水高山，花前慢奏。"]},{"t":"舞春风 咏花幡，并序","f":"七言律诗","c":["剪帛裁成五色幡。","枝头高挂舞翩翩。","才过谷雨看花日，恰好东风结果天。","嫩蕊更须人护惜，柔条为怕鸟衔残。","倚阑细玩生生理，可喜矫儿善保全。"]},{"t":"水调歌头 湘佩属题《清惠堂遗印诗》","f":"古风","c":["香火岁时祭，湖水似臣心。","清流不断，千年姓字列东林。","未了生前遗憾，岂是先生力薄，无计破群阴。","固有浩然气，天地是知音。","二百载，方寸石，竟难沈。","人间万事，忧喜得失古犹今。","天道好还之理，旧物完璞不损，四字抵千金。","永锡子孙福，世守此规箴。"]},{"t":"莺啼序 雨中送春，用吴梦窗韵","f":"古风","c":["三春又轻过了，叹韶华似水。","画阑外、几树飞花，可怜剩有残蕊。","便是果成时已过，飘零艳色随风坠。","听娇莺声细。","凄凄似有愁思。","天也无情，迅如过羽，宿雕梁燕子。","尚能记、当日双栖，故巢收拾又至。","暗窥人、新愁旧恨，泻珠泪、偷弹纤指。","怕匆匆，花与春归，又生凉意。","陈踪旧迹，闷闷愁愁，尽酿成梦寐。","吹柳絮、绿绵不定，淡霭微雨，扫尽残红，落花如泪。","岂因病酒，愁宽梦窄，谁能怜取新来瘦，试春衣、顿觉身憔悴。","娇香易减，翩翩蛱蝶探芳，往来海棠阴里。","阶前绿满，琐琐游蜂，也惜红慕翠。","怅昔日花间游憩。","览胜登临，拾蕊拈花，不堪题起。","萍飘浪泊，难追欢事。","东风门巷春已去，恋余香，空向阑干倚。","如今检点新词，为饯花魂，泪盈素纸。"]},{"t":"古香慢 题竹溪老人墨牡丹画册","f":"古风","c":["纸光墨彩，神韵如生，当日亲写。","慢展遗篇，尚有暗香未化。","重见古精神，恍疑是、瑶池摘下。","洗铅华扫尽俗态，淡妆别样娴雅。","想当日、公余之暇，收拾名花，香绕庭榭。","笔墨消闲，岂为世间声价。","闭户守图书，性高尚、交游亦寡。","有贤郎，继家学、篆书堪亚。"]},{"t":"金缕曲 题蒲察夫人《闺塾千字文》⑴","f":"古风","c":["肃肃金闺彦。","古蒲察、巍巍令族，声名久远。","彤管一枝承内则。","不写春愁秋怨。","更不假、花针柳线。","千字文章传千古，又何劳、列女纷纷传。","风人旨，异堪羡。","鸥波故事今重见。","几生中、双修福慧，才人淑嫒。","绣虎雕龙天付与，好是骊珠一串。","能使我、读之不倦。","俚句勉题容附翼，忝同宗、何故相知晚。","何日欲，会君面。"]},{"t":"醉翁操 题云林湖月沁琴图小照","f":"楚辞体","c":["悠然。","长天。","澄渊。","渺湖烟。","无边。","清辉灿灿兮婵娟。","有美人兮飞仙。","悄无言。","攘袖促鸣弦。","照垂杨、素蟾影偏。","羡君志在，流水高山。","问君此际，心共山闲水闲。","云自行而天宽，月自明而露漙。","新声和且圆，轻微徐徐弹。","法曲散人间。","月明风静秋夜寒。"]},{"t":"雪狮儿 雪窗漫成","f":"古风","c":["低帷伏枕，重衾恋卧，疏窗清晓。","蜡泪盈盈，小盎菊花香老。","鸟惊树杪。","问昨夜、寒添多少。","起来看、阶前栏外，乱琼纷绕。","嘱付双鬟莫扫。","爱天然、作就画材诗料。","袖手无言，会处翻然成笑。","半生潦倒。","拚一醉、消除怀抱。","凭谁告。","托向美人芳草。"]},{"t":"秋波媚 夜坐","f":"古风","c":["自笑当年费苦吟。","陈迹梦难寻。","几卷诗篇，几张画稿，几许光阴。","唾壶击碎频搔首，磨灭旧胸襟。","而今赢得，千丝眼泪，一个愁心。"]},{"t":"金缕曲 上定郡王筠邻主人","f":"古风","c":["人世诚难料。","叹英雄、未完夙志，天何草草。","母子孤孀无人问，谁许王孙哀告。","空搔首、难舒怀抱。","可也九泉能念我，掩啼痕、独向风前悼。","写不尽，招魂稿。","沈忧损性成颠倒。","感清天、一声霹雳，阴霾都扫。","拯救生民稍援手，泛出慈航仙棹。","更无尽、神光普照。","虽有覆盆终解释，此生恩、拟向来生报。","聊献上，陈情表。"]},{"t":"满江红","f":"古风","c":["冒雪冲寒，崎岖路、马蹄奔走。","望不尽、远山冠玉，六花飞凑。","碧瓦遥瞻心似剖，殡宫展拜浇杯酒。","哭慈亲、血泪染麻衣，斑斑透。","故人意，休辜负。","乡间味，甘消受。","费松柴一灶，余粮半斗。","好客岂拘贫与富，充饥莫论精和陋。","饭王孙、粗粝菜根香，逢漂母。"]},{"t":"金缕曲 王子兰公子 寿同 寄词见誉，谱此致谢，用次来韵","f":"古风","c":["今古原如此。","叹浮生、飞花飘絮，随风已矣。","落溷沾茵无定相，最是孤臣孽子。","经患难、何曾容易。","况是女身兼薄命，愧樗材、枉受虚名被。","思量起，空挥涕。","古人才调诚难比。","借冰丝、孤鸾一操，安排宫徵。","先世文章难继绪，不过扶持培置。","且免个、鹑衣粟米。","教子传家惟以孝，了今生、女嫁男婚耳。","承过誉，感无已。"]},{"t":"满庭芳 雨中过含芳园，谒筠邻主人","f":"古风","c":["步入名圃，豁然开眼，茂林修竹怡人。","一湖春水，烟树渺芳津。","恰值丝丝疏雨，板桥外、山势嶙峋。","通幽径，回廊曲折，环带草如茵。","锦堂人住处，帘风砚水，几案无尘。","更多少琴书，绕座相亲。","咳唾成珠成玉，为善乐、恬淡精神。","汪洋论，顺时知命，德也本乎仁。"]},{"t":"占春芳 戏咏瓶中柳枝杏花","f":"古风","c":["红杏艳，绿杨袅，相与共扶春。","供向云房深处，案头留住芳辰。","一段好精神。","小瓶儿、清水无尘。","怕教容易随风去，飞过比邻。"]},{"t":"忆仙姿 戏咏瓶中褕叶梅寿丹","f":"古风","c":["瓶里春光如绣。","榆叶梅花秾茂。","妙色可人心，更有金丹延寿。","微漏。","微漏。","特把名儿相凑。"]},{"t":"高阳台 前三月廿九红雨轩送春，用有正味斋春尽日韵","f":"古风","c":["春到无言，春归似梦，迅如逝水流船。","多愁多病，羸躯挨过年年。","今年花事虽逢闰，祝封姨、更要相怜。","莫将他、堕粉飘香，断送如烟。","枝头渐已成青子，怪游蜂浪蝶，逐日常川。","何事飞花，偏教先到愁边。","伤春自吊埋香冢，葬胭脂、净土长眠。","五更头、风风雨雨，老却啼鹃。"]},{"t":"惜余春慢 闰三月三日，邀云林、湘佩红雨轩赏海棠，座中分咏，即用有正味斋韵","f":"古风","c":["垂柳藏鸦，海棠迷蝶，浅浅深深难说。","春虽逢闰，生怕随春，轻卸画阑干外。","一夜东风怎禁，撼损娇姿，嫩枝惊折。","扑帘栊几点，飞花吹起，满庭红雪。","为留取、有限风光，深怜痛惜，绣作舞衣罗袜。","柔枝细亸，彷佛当年，睡起那番标格。","旧事休题，且拚共倒芳樽，落花时节。","恨春归夏至，红稀绿密，有谁留得。"]},{"t":"沁园春 题《茂陵弦传奇》","f":"古风","c":["孑然一身，四海倦游，多病多情。","正锦城春色，都亭逆旅，江山历历，花柳荣荣。","有女怀春，文君新寡，法曲当筵一再行。","琴心挑，托求凰有凤，暗里人听。","风流不避浮名。","竟相就、同谐百岁盟。","便当街涤器，当炉卖酒，胸襟洒落，词赋纵横。","文赚千金，名传千古，封禅遗书孰与更。","回首处，剩琴台日暮，芳草青青。"]},{"t":"满庭芳 次筠邻主人咏牡丹原韵","f":"古风","c":["剪到秾香，清和天气，映空雾雨轻匀。","这般态度，谁敢斗鲜新。","国色天香富贵，瑶池种、迥出凡尘。","雕阑护，姚黄魏紫，深浅总宜人。","更谁相问讯，绡窗掩日，苔径留春。","飐帘旌风软，花影清真。","不管杨花榆荚，肃端庄、一段精神。","凝妆处，玉壶亲贮，词客醉芳茵。"]},{"t":"满庭芳 次筠邻主人咏絮原韵","f":"古风","c":["倦绣停针，摊书小卧，流莺恰恰殷勤。","东风帘幕，春老饯花魂。","最是韶光难系，渺茫茫、来去无痕。","无端底，风前弱絮，也会自纷纷。","颠狂飞不定，恼人情绪，暗度朝昏。","惹秋千红索，风月柴门。","零乱沾茵落溷，无凭准、勾起愁根。","天涯路，千团晴雪，飘舞过邻园。"]},{"t":"江神子 浴佛日喜雨","f":"古风","c":["阿香油壁碾轻车。","电光加。","掣金蛇。","一夜甘霖、普济万千家。","今岁麦秋知有望，民之乐，乐无涯。","新荷闹雨听鸣蛙。","绿阴遮。","暗窗纱。","晓起钩帘、残溜滴檐牙。","人向画栏干畔立，罗衫薄，受风斜。"]},{"t":"凄凉犯 题秋窗染翰图","f":"古风","c":["愁难寄托。","萧条甚、情丝怎系离索。","美人去后，余香尚在，袖稍襟角。","罡风最恶。","未必算、卿卿福薄。","忆当初、修嫭连娟，肠断旧标格。","不堪回首处，霜陨秋荷，钗分金雀。","姗姗月底，待招来、望中魂魄。","未了今生，或能够、来生会著。","散花人、结习空时无所缚。"]},{"t":"南乡子 端阳后一日，四女仲文以玻璃小屏乞画兰花并索题，遂作此","f":"古风","c":["节候过端阳。","风雨连朝作嫩凉。","画阁卷帘同笑语，琼浆。","蒲叶榴花泛玉觞。","薄醉写秋芳。","娇女牵农向阿娘。","更要新诗题几句，微茫。","记出离骚一段香。"]},{"t":"青山相送迎 藩王杏庄婿⑴以塞上景团扇属题","f":"古风","c":["角声悲。","雁行归。","苜蓿西风战马肥。","毡庐傍水支。","塞云飞。","暮烟炊。","野岸平沙细柳垂。","秋山积翠微。"]},{"t":"惜秋华 题竹轩王孙 祥林 小照","f":"古风","c":["万里高空，度西风、画出一行飞雁。","三径菊花，东篱露黄开遍。","遥山淡染青螺，爱野色行寻步缓。","消遣。","惜秋光、好把寒香偷剪。","不问秋深浅。","待白衣送酒，倒翠樽花畔。","消遥甚、更脱帽，垂襟疏懒。","王孙富贵风流，况大隐、旁人争羡。","舒眼。","任天涯、日酣云展。"]},{"t":"玲珑四犯 自制凤凰衣萤灯","f":"古风","c":["腐草为萤，爱几处辉辉，花底池畔。","拍手儿童，争扑素罗纨扇。","偏又巧入疏帘，暗度过、镜奁书案。","点画屏、高下飞遍。","比似柳花轻便。","练囊不为吟诗剪。","慢兜来、冷光成片。","一丸挂向纱帷里，留待更深看。","最好梦乍回时，明灭影、残灯分焰。","听小窗微雨，更不避，风吹乱。"]},{"t":"山鬼谣 山楼听雨有感","f":"古风","c":["倚危阑、半阴斜日，野云窗外飞起。","山楼乍满西风冷，襟袖暗沾烟水。","云际里。","分不出、浓青淡绿苍茫耳。","空濛眼底。","但电掣金蛇，雷惊幽谷，尘世亦闻否。","黄昏后，入夜时鸣不已。","旧游今昔难比。","年来多病身心懒，独坐剪灯凭几。","愁难理。","慢付与、青笺斑管从头纪。","伤心已矣。","奈听雨听风，恼人滋味，愁可有涯涘。"]},{"t":"南柯子 中元由金顶山回南谷山中书所见","f":"古风","c":["絺绤生凉意，肩舆缓缓游。","连林梨枣缀枝头。","几处背阴篱落、挂牵牛。","远岫云初敛，斜阳雨乍收。","牧踪樵径细寻求。","昨夜骤添溪水、绕村流。"]},{"t":"比梅 清明前二日，墙角白桃花为风雪损坏","f":"古风","c":["比到梅花憨弱。","比到梨花轻薄。","先占早春开，却也丰姿绰约。","吹落。","吹落。","怪煞雪风交作。"]},{"t":"蓦山溪 慈溪看捕鱼作","f":"古风","c":["垂杨枝外，一片桃花水。","临水野人家，好生涯、叉鱼活计。","疏篱草舍，三五自成村，称鱼市，儿童戏，也效叉鱼技。","飞花万点，乱卷东风起。","晒网趁斜阳，射金波、落霞影里。","言斤论两，鱼价细评量，同妇子，谋生耳，此外无余事。"]},{"t":"诉衷情令 咏墙东海棠","f":"古风","c":["欲开犹敛意融融。","丰韵特娇慵。","担荷春光多少，生怕动微风。","扶绛萼，倚芳丛。","粉墙东。","好花易落，者些态度，谁适为容。"]},{"t":"沁园春 落花","f":"古风","c":["点点星星，零零落落，一片飞残。","向东风影里，空劳蛱蝶，碧纱窗外，遮没阑干。","柳线难牵，帘钩难挂，无赖封姨不见怜。","经行处，恰纷纷红雨，轻拍香肩。","芳魂何处姗姗。","待剪纸、招来月下看。","认朦胧不准，飘摇不定，烟清雨化，丰韵难传。","惯为花愁，谁禁又落，空对长条不忍攀。","从今后，剩绿苔庭院，吹满榆钱。"]},{"t":"惜春郎 送春","f":"古风","c":["剩脂残粉谁收拾。","枉累人愁泣。","阑干十二，藓阶苔径，春恨如织。","几度留春留不得。","拟痛饮今夕。","葺落花、作个青心，也算是怜春色。"]},{"t":"海棠春 自题画海棠，用秦少游韵","f":"古风","c":["借来数朵花枝巧。","更不许、蝶蜂知觉。","放下水晶帘，相伴炉烟袅。","何劳窗外流莺报。","且看取、风光占早。","留得四时春，岂在花多少。"]},{"t":"洞仙歌 集《楚辞 山鬼章》字","f":"楚辞体","c":["有人窈窕，表灵旗云路。","独立幽篁被蘅杜。","杳冥冥、松柏昼晦山阿，憺忘归，采秀折兰带薜。","芳馨结不得，宜笑修容，既见慕兮又含睇。","石荫葛蔓蔓，猿木萧萧，疑然作、夜鸣飘雨。","怨险磊、车乘怅离忧，徒遗我、难留所思之处。"]},{"t":"明月棹孤舟 题钊儿画茅舍归舟","f":"古风","c":["缥缈长天山影淡。","认前村、维舟收缆。","树绕垂藤，柴门篱落，灯火幽窗阴暗。","半隐陂陀临水占。","挂凉蟾、寒光如鉴。","西塞山边，烟蓑雨笠，消受风恬云敛。"]},{"t":"一剪梅 月夜独酌","f":"古风","c":["寂寞空庭月一方。","窗里灯光。","帘外天光。","深杯独酌耐微凉。","诗尽枯肠。","酒满愁肠。","交枝花影不成行。","才下回廊。","又上东墙。","三更敲过夜何长。","收拾匡床。","炷好炉香。"]},{"t":"辊绣球 咏绣球梅","f":"古风","c":["花样忒玲珑，攒簇处、纤秾如绣。","碧揉云碎，红蒸霞浅，画阑西畔，彩球五色，荡摇清昼。","正是绿肥时候，偏越越、粉凝脂溜。","可人姿致，况开长久。","多情蛱蝶，成团逐队，也来飞凑。"]},{"t":"定风波 城东泛舟","f":"古风","c":["侵晓城东泛画桡。","天光云影碧迢迢。","少长同游随处好。","恰巧。","荷花生日是今朝。","极目蒹葭浮两岸。","一片。","小楼临水酒帘飘。","听彻潺湲飞渡口。","更有。","乱蝉声曳绿杨梢。"]},{"t":"惜秋华 壬寅七月廿一，重睹邱中天游阁旧居有感","f":"古风","c":["旧梦天游，倚晴空、犹是当年楼阁。","绣户绮窗，蛛丝暗牵帘幕。","纵横薜荔缘阶，隐幽径、兔葵燕麦。","萧索。","噪斜阳，剩有营巢鸟雀。","认取阑干角。","乱蓬蒿掩处，绽海棠红萼。","景如此，人非昔，向谁寄托。","不堪四载重来，怅怀抱、情伤心恶。","难著。","对西风、泪痕吹落。"]},{"t":"看花回 题湘佩妹梅林觅句小照","f":"古风","c":["忽见横枝近水开。","香逐风来。","惜花人在花深处，倚绿筠、几度徘徊。","前身明月是，应伴寒梅。","冰作精神玉作胎。","天付奇才。","怕教风信催春老，捻花枝、妙句新裁。","暗香疏影里，立尽苍苔。"]},{"t":"瑶台聚八仙 祝芸台相国八十寿","f":"古风","c":["霞帜云标。","瑶池诏、丹筹衔出重霄。","寿添百禄，遥见鹤舞飘飖。","彩服斑衣呈寿斝，芝田术圃献灵苗。","颂歌谣。","纪功述德，名重三朝。","娱老。","放怀山水，拥商彝夏鼎，紫绶金貂。","选楼别墅，清凉远避尘嚣。","东风又传春信，到嫩柳、新波廿四桥。","韶光好，任老人行乐，扶杖逍遥。"]},{"t":"暗香疏影 自题淡月疏梅","f":"古风","c":["昏黄淡月。","浸水边篱下，缟衣莹洁。","仙骨珊珊，占断小园风景别。","认取朦胧影子，娴雅处、丰姿清绝。","恍又是、水面低窥，窗外一枝瞥。","羞与众芳摇落，孤高竟不与、众芳争悦。","冷淡生涯，冰玉精神，耐到东风时节。","巡檐写出罗浮稿，忍便共、凡花轻折。","任横斜、素壁移灯，印上半林香雪。"]},{"t":"上升花 自题画红梅","f":"古风","c":["门掩空庭，疏窗上、移来月明如画。","飞入暗香，知有梅花，早见影儿相凑。","古欢自与幽人结，朦胧处、一枝低覆。","问何事、依依倦倚，恁般清瘦。","欲画偏难下手。","看绛萼，琼英粉凝脂溜。","绮丽丰姿，淡泊精神，允称百花居首。","想当微雪轻烟候，闲作个、胎禽厮守。","相许否。","巡檐试开笑口。"]},{"t":"庭院深深 杏庄婿属题络纬美人团扇","f":"古风","c":["开到黄花秋老，凉风吹过妆楼。","云鬟宫样罢梳头。","绮窗无个事，晓日上帘钩。","细检瓜瓤菜叶，爱听络纬声幽。","持来素手慢凝眸。","想因观物化，应不解悲秋。"]},{"t":"醉太平 四女仲文索题戏婴图","f":"古风","c":["雕阑月明。","梅花韵清。","竹枝满地纵横。","听儿童笑声。","风庭露庭。","谁家弟兄。","人间至乐真情。","兆多男戏婴。"]},{"t":"醉春风","f":"古风","c":["趋造高人馆。","不避泥涂烂。","多情留客具盘餐，劝。","劝。","劝。","酒泛金杯，菜香犀箸，瓜陈玉盘。","雨过闲庭院。","风引轻罗扇。","主人含笑嘱回头，看。","看。","看。","窗外新栽，榴花一丈，绿阴遮满。"]},{"t":"桃园忆故人 题纫兰妹兰风展卷小照","f":"古风","c":["故人寄到兰风卷，快睹画中人面。","七载丰姿微变，不似当初见。","从新拭目从新看，转觉愁添恨满。","数字真情写遍，托付南归雁。"]},{"t":"惜黄花 题张孟缇夫人淡菊轩诗舍图","f":"古风","c":["秋容围屋，诗声谁读。","伴黄花，绕疏篱、几竿修竹。","插架秘图书，博览堪游目。","好生活、古香充腹。","丰神静肃。","墨华芬馥。","羡伊人，羡伊人、享全清神，彤管振琳琅，闺阁知名宿。","雅称个、纫兰餐菊。"]},{"t":"多丽 题翁秀君女史群芳再会图","f":"古风","c":["众香国，问谁管领群芳。","展冰绡、研朱滴粉，安排疏密停当。","借传神、散花妙手，环肥燕瘦几评量。","含露临风，拒霜擎雨，蕊宫仙子斗新妆。","更看取、霓旌霞葆，掩映影苍茫。","应不许、天风吹损，离合神光。","算前身、司花是惯，自然结习难忘。","拈霜毫、慢渲细染，花随腕底散天香。","故向人间，流传神品，千年艳质好收藏。","看不足、陆离交错，颠倒费端详。","端详处、花花叶叶，皆是文章。"]},{"t":"玉交枝 上元屏山生日，过堪喜斋，滇生大司马属咏白牡丹","f":"古风","c":["天上人间，月明灯夕，蓦遇蕊宫仙子。","帘卷东风春满座，众里谁能相比。","霓裳金带，半拖烟雾朦胧，瑶池初下应如是。","生怕夜寒料峭，微风斜倚。","天然素质端方，不须假借，淡妆翻称容止。","且留住、仙裾缟袂，莫轻举、乘鸾飞起。","恰宜在、深深院里。","锦堂香暖尚书第。","素富贵长春，对花共醉红灯底。"]},{"t":"愁春未醒 梦题雕阑细草图，醒记其末二句，足成此阕","f":"古风","c":["雕阑细草，碧户红窗交荫。","正轻暖轻寒时候，帘幕沈沈。","淡荡微烟，一天云影护芳林。","几番风信，十分雨意，酿出花心。","恍惚旧游，依稀重到，曲径斜临。","最堪笑、披图觅句，谁索闲吟。","梦乍回时，慢思量处杳难寻。","谁家池馆，深深庭院，都是春阴。"]},{"t":"新雁过妆楼 雪夜闻雁","f":"古风","c":["静掩重门。","春塞重、鸦栖又到黄昏。","乱飘琼蕊，堆满瓦陇墙根。","好共梨花争素质，欲同柳絮斗轻魂。","舞翩翻。","小窗浙沥，乌鹊惊喧。","有人摊书独坐，正炉添活火，茶熟香温。","夜冷风凄，东君锁住春痕。","铜壶三传漏永，照孤影、残灯一豆存。","更深也，听雁声嘹唳，飞过前轩。"]},{"t":"桃花水 浴鹅","f":"古风","c":["东风细细柳丝丝。","泥人春日迟。","微波动，碧参差，暗水涨新池。","独自倚栏时。","对涟漪。","清流何事最相宜。","浴鹅儿。"]},{"t":"风蝶令 春日游草桥，过菜花营看竹","f":"古风","c":["春水才平岸，蛙声已满塘。","蘋丝分绿映垂杨。","几处浣衣村妇、淡梳妆。","看竹疏篱外，停车老树旁。","李花零落杏花香。","一带小桃花底、菜花黄。"]},{"t":"南乡子 上巳前一日，同屏山、云林、云姜游可园，园为宗室崇文别墅","f":"古风","c":["郊外按呜驺。","行过城西二里沟。","老树长藤交映处，临流。","隐约王孙别墅楼。","花坞曲通舟。","细水平堤绿更柔。","开到海棠春正好，悠悠。","人在湖山画里游。"]},{"t":"殢人娇 题扇头簪花美人","f":"古风","c":["香袅金猊，恰恰兰衾梦醒。","卖花声、催人临镜。","牡丹开矣，正燕巢初定。","妆台畔、慢把玉容重整。","鬓影蝉轻，眉痕翠凝。","天作就、爱花心性。","一枝斜插，与乌云相并。","添妩媚、信手簪来偏称。"]},{"t":"定风波 咏紫玉簪","f":"古风","c":["秋雨浪浪湿碧苔。","庭花无数雨中开。","一种看来颜色好。","袅袅。","浑疑仙子御风来。","羽盖似将云影护。","丰度。","罗衣偏爱淡霞裁。","应是玉妃微醉后。","轻溜。","鬓边卸下紫鸾钗。"]},{"t":"燕山亭 清明后一日，用曝书亭《清明日饮杏花下》韵","f":"古风","c":["已过清明，社燕初来，风信几番吹透。","红了杏花，白了梨花，绿遍池塘杨柳。","恰恰娇莺，听帘外、新簧圆溜。","依旧。","到乍试春衣，海棠时候。","不是旧时人面，奈多病多愁，花能知否。","鬓丝禅榻，寂寞闲窗，堪笑有花无酒。","意懒心慵，偏遇者、困人长昼。","回首。","春渐老、花飞渡口。"]},{"t":"早春怨 春夜","f":"古风","c":["杨柳风斜。","黄昏人静，睡稳栖鸦。","短烛烧残，长更坐尽，小篆添些。","红楼不闭窗纱。","被一缕、春痕暗遮。","淡淡轻烟，溶溶院落，月在梨花。"]},{"t":"菩萨蛮 次湘佩鹊","f":"古风","c":["春阴乍合云偏散。","幽窗更觉愁人倦。","辜负看花天。","黄尘杂柳烟。","三分春正好。","弱絮黏芳草。","难熨小眉痕。","相怜镜里人。"]},{"t":"菩萨蛮","f":"古风","c":["海棠倦倚东风重。","梨花共结同心梦。","阶下自徘徊。","苔侵金缕鞋。","春光深几许。","共坐花前语。","风动柳毵毵。","花酣酒亦酣。"]},{"t":"金缕曲 题吴淑芳夫人霜柏慈筠图","f":"古风","c":["妙手传神似。","画图中、雍雍肃肃，端方容止。","自是君身有仙骨，福慧双修如此。","堪称得、扫眉才子。","先世延陵遵古训，守诗书礼乐司中馈。","甘淡泊，厌罗绮。","虚堂把卷双鬟侍。","对芳塘、一泓澄碧，轻阴满地。","此际身心清凉甚，兀坐嗒然隐几。","数十载、辛勤非易。","霜柏慈筠同苦节，感仙人降笔分明示。","传佳话，重乡里。"]},{"t":"虞美人 雨中答湘佩","f":"古风","c":["秋来比似春时瘦。","空度如年昼。","喓喓虫语报西风。","早又银床一叶、落梧桐。","经旬霪雨难寻胜。","积水连花径。","苔痕草色映罗襟。","时有竹梢相触、似鸣琴。"]},{"t":"醉花阴 咏蝶","f":"古风","c":["淡绿轻红春日暖。","落瓣随风卷。","蝶阵趁飞花，欲绣翩翩，抽尽春蚕茧。","滕王旧稿晴窗展。","住住飞飞缓。","花底作生涯，心醉群芳，生受东君管。"]},{"t":"丑奴儿 春日偶成","f":"古风","c":["已过谷雨春将暮，未见花开。","未见花开。","辜负多情燕子来。","海棠憔悴东风老，绿叶成阴。","绿叶成阴。","银烛烧残无处寻。"]},{"t":"琐窗寒 题冬闺刺绣图","f":"古风","c":["弱线初添，琐窗渐暖，闭门同绣。","明金压线，刺出一痕春透。","慧心儿、花样细翻，各人施展纤纤手。","意迟迟、几度停针，生怕作来肥瘦。","低首。","双眉暗斗。","正无语思量，阿谁轻逗。","香肩慢扣，指点绿平红绉。","踏春郊、芳草落花，缓步不染星星垢。","舞回风、小立秋千，试问谁能够。"]},{"t":"忆人人 送屏山往杭州","f":"古风","c":["留君不住，送君不舍，一片离愁难说。","虽云暂别亦相思，反不及、交情淡薄。","秋风秋雨，长途珍重，况是凄凉时节。","临歧把袂问归期，莫恋着、家山丘壑。"]},{"t":"鹊桥仙 初冬云林邀同家霞仙龙爪槐看菊，过陶然亭望西山","f":"古风","c":["故人邀我，城南访菊，已过黄花时节。","更从何处问秋芳，见一路、霜林残叶。","蒹葭阁下，陶然亭外，剩有寒芦如雪。","冷烟薄雾淡斜阳，望不见、西山重叠。"]},{"t":"早春怨 题蔡清华夫人桐阴仕女图","f":"古风","c":["云净天空。","苔阶露坐，夜色溶溶。","一扇微凉，一轮明月，一树疏桐。","安排肥瘦纤秾。","费老手、传神特工。","纸上丰姿，画中态度，谁个真容。"]},{"t":"喝火令 戊申新秋望日偶成","f":"古风","c":["残暑留余热，罗纨尚未捐。","露华庭院早秋天。","又到一年今夕，七见月团圆。","深草藏萤火，凉蝉咽柳烟。","生憎虫语太缠绵。","恼煞喓喓，恼煞搅人眠。","恼煞几重花影，和月到帘前。"]},{"t":"长相思 已酉正月廿四，雪窗寄湘佩二首，用独木桥体 其一","f":"古风","c":["过新年。","贺新年。","马齿空加又一年。","浮生能几年。","是今年。","是明年。","试问君归在那年。","愁人日似年。"]},{"t":"长相思 已酉正月廿四，雪窗寄湘佩二首，用独木桥体 其二","f":"古风","c":["花开时。","雁来时。","草色遥看是此时。","同游记旧时。","忆君时。","寄君时。","写到相思两字时。","伤心下笔时。"]},{"t":"贺新凉 雨中晓发南谷，用蒋竹山韵","f":"古风","c":["几阵鸡鸣了。","听潇潇、雨声不住，天光渐晓。","料理行装催早发，多是崎岖山道。","况秋潦、行人更少。","夹路山花如堆锦，载秋光不尽车箱小。","丹砂颗，缀酸枣。","长空不肯阴云扫。","荡烟丝、垂杨处处，凉蝉嘶老。","禾黍披离高原上，一夜西风吹倒。","涨溪水、孤村环抱。","转过云岗回头望，认依稀、高岭横天杪。","云又起，四山杳。"]},{"t":"南柯子 九日城南看菊","f":"古风","c":["问菊城南路，秋光又一年。","草桥风景尚依然。","正是黄花时节、碧云天。","荒草迷幽径，残芦被野田。","丝丝衰柳挂寒烟，遥指半规斜日、隐山巅。"]},{"t":"满江红 九日屏山、湘佩招游悯忠寺","f":"古风","c":["时节重阳，喜良友、相邀消遣。","向古寺、驱车访菊，黄花不见。","败叶凋伤零落舞，残碑剥蚀摩挲看。","葬忠魂、千古此高台，凭人赞。","如来法，慈悲愿。","刹那顷，韶光换。","忆旧游重到，临风自叹。","回首竟成今昔感，宽心且作嬉游忭。","约明年、此会共登临，知谁健。"]},{"t":"云淡秋空 八月廿一，屏山姊招看桂花","f":"古风","c":["傍午忽传。","良朋邀我，秋色同看。","金粟香飘，碧天云淡，画阁人闲。","郇厨珍品堆盘。","酌杯酒、纱窗曲栏。","帘卷西风，衣添半臂，共醉花间。"]},{"t":"金风玉露相逢曲 谢湘佩寄并州剪","f":"古风","c":["芭蕉敲雨，梧桐坠露，又是新秋到了。","无心写景欲言情，当不得、神魂颠倒。","萧斋兀坐，愁怀难遣，恰好故人书到。","并州快剪寄将来，剪不断、相思萦绕。"]},{"t":"金缕曲 题《行有恒堂词集》","f":"古风","c":["镂月裁云手。","好文章、天衣无缝，神针刺绣。","写景言情无不切，一串骊珠穿就。","应不数、豪苏腻柳。","脱尽人间烟火气，问前身、金粟如来否。","餐妙句，淳如酒。","神龙变化云出岫。","笔生花、篇篇珠玉，锦心绣口。","文彩风流谁得似，明月梅花为偶。","比修竹、孤高清瘦。","岂止新词惊人眼，行有恒、事事存心厚。","三复读，味长久。"]},{"t":"画屏秋色 屏山邀看菊","f":"古风","c":["窗外天光暝。","素壁前、添出几重花影。","移座对花，故烧高烛，花叶光莹。","染襟袖香清，短屏低护似更称。","带暗霜、枝上凝。","看嫩碧娇黄，淡红浓紫，最是细玲珑处，浅深相映。","枝梗。","斜斜整整。","斗艳妆、粉黛交逞。","者般风景。","依依良夜，漏传酒醒。","愧座客新诗未成，空负红烛冷。","壁上稿、重再省。","欲写出丰神，年来心绪不定。","且把秋容慢咏。"]},{"t":"鬓云松令 题梦兰夫人画扇","f":"古风","c":["乍长天，清昼永。","风荡帘钩，午梦人初醒。","纤手慢将云鬓整。","美目流波，花底新妆靓。","对芳菲，心自省。","花静人娴，人与花相称。","空谷一枝谁解赠。","谱入离骚。","添个幽兰影。"]},{"t":"意难忘 哭云林妹","f":"楚辞体","c":["十载思量。","幸莲舆北上，重睹容光。","芳颜仍似玉，云鬓却成霜。","相把袂，语悲伤。","说离乱兵荒。","叹年来，惊惊恐恐，无限凄惶。","忽然病入膏肓。","是长途辛苦，体不禁当。","君心应自在，我意竟难忘。","持素手，断柔肠。","问去者何方。","望魂兮，魂兮早降，享我杯浆。"]},{"t":"减字木兰花 春雨次韵","f":"古风","c":["柳丝长短。","约住春阴人意懒。","夜雨凄凄。","不许催归杜宇啼。","清明时候。","料峭轻寒偏迤逗。","九十春光。","花信才传到海棠。"]},{"t":"菩萨蛮 拟古春闺次韵","f":"古风","c":["小楼日倚阑干遍。","恼人最是风前燕。","望远豁双眸。","垂杨满陌头。","遣愁无处着。","翠被和愁卧。","香篆霭重帘。","春寒梦里添。"]},{"t":"齐天乐 题孚斋王孙乘槎载妓圆","f":"古风","c":["聚香国里香风起，灵槎御风而下。","天女腰肢，维摩眉宇，闻是王孙自写。","欲何为也。","有百八牟尼，一函般若。","不著纤尘，屏除一切更娴雅。","本来心在云水，现官身说法，恁般潇洒。","不染峰峦，不增泉石，一片青天光射。","翠鬟娇姹。","岂谢傅东山，管弦游冶。","载个人儿，散天花侍者。"]},{"t":"踏莎行 冬夜听歌","f":"古风","c":["镂月裁云，移宫换羽。","歌喉怕惹娇莺妒。","浅斟不问夜何其，三星早已当门户。","彩袖高扬，柘枝低舞。","檀槽慢捻冰弦柱。","曲终明月送人归，小庭深院霏寒雾。"]},{"t":"滴滴金 四月廿九，谢志邸莲舫主人见惠鲜枇杷","f":"古风","c":["初晴快雨垂帘坐。","忽朱邸、颁珍果。","案头细细自开封，是枇杷些个。","清芬滋味黄金颗。","慢奇擎、莫教破。","不尝此味已多年，谢主人怜我。"]},{"t":"南乡子 咏瑞香","f":"古风","c":["花气霭芳芬。","翠幕重帘不染尘。","梦里真香通鼻观，氤氲。","不是婷婷倩女魂。","细蕊缀纷纷。","淡粉轻脂最可人。","懒与凡葩争艳冶，清新。","赢得嘉名自冠群。"]},{"t":"风光好 同治甲子元日，戏题多儿图⑴","f":"古风","c":["柳绵绵。","水涓涓。","嬉戏群儿小河湾。","舞雩天。","谁家特染丹青笔。","多男子。","吉兆欣逢甲子年。","乐无边。"]},{"t":"金缕曲 题俞彩裳女史《慧福楼诗集》","f":"古风","c":["福慧双修矣。","问芳龄、二八年纪，聪明如此。","一卷新诗出示我，美玉精金堪比。","真不愧、诗书门第。","拈出卷中读史句，岂寻常、弄月吟风耳。","簪花格，银钩字。","瑶池仙子应如是。","爱翩翩、温柔态度，端庄容止。","恰有仙郎成伉俪，一对璧人双美。","堪称得、扫眉才子。","况又人言知孝道，侍孀姑膝下呈欢喜。","福与慧，更谁似。"]},{"t":"贺新凉 代人题竹深荷净图","f":"楚辞体","c":["荷净竹深处。","爱修篁、虚心直节，红莲解舞。","应是碧天新雨霁，消尽人间烦暑。","一阵阵、微风香度。","人与花兮同洁净，薄绡衣、不许纤尘污。","坐磐石，对芳渚。","风流文彩堪称许。","画图中、修眉隆准，精神楚楚。","福慧双修谁得似，况又宽容仁恕。","为善乐、受天之佑。","此际身心清凉甚，淡襟怀、潇洒得佳趣。","应添入，神仙谱。"]},{"t":"金风玉露相逢曲 丙寅中秋，是日秋分","f":"古风","c":["天光如水，月光如镜，一片清辉皎洁。","吹来何处桂花香，恰今日、平分秋色。","芭蕉叶老，梧桐叶落，老健春寒秋热。","须知光景不多时，能几见、团圆佳节。"]},{"t":"金缕曲 送屏山姊扶柩旋里","f":"古风","c":["岂是无情者。","遥将归、家山安葬，匆匆车马。","此去长途须保重，仔细雨天风夜。","况已是、暮年人也。","卅载交情如手足，怅离怀、多少伤心话。","难把你，车儿把。","牵衣执手偏难舍。","盼鱼书、总然数字，也须亲写。","我本多愁君善病，两地情牵意惹。","梦不到、横河宅舍。","硬著心肠真个去，此时情、何日方能罢。","相思泪，风前洒。"]},{"t":"西江月 秋日游鲇鱼关，晚过栖云道院，四十年风景变迁，得不有感","f":"古风","c":["鹦鹅湾头秋水，鲇鱼关外西风。","崇山峻岭几多重。","归路斜阳相送。","宛转长城如带，崎岖樵径斜通。","栖云道院扣仙宫。","四十年来一梦。"]},{"t":"醉太平","f":"古风","c":["风清月清。","鸾呜凤呜。","谁家绣阁娉婷。","借冰丝写情。","云声水声。","鱼听鹤听。","恼人好梦偏惊。","是山灵化成。"]},{"t":"西江月 光绪二年午日，梦游夕阳寺","f":"古风","c":["寻得夕阳小寺，梅花初放厓阿。","一湾流水绕陂陀。","细路斜通略约。","好梦留连怕醒，偏教时刻无多。","登山临水乐如何。","好梦焉能长作。"]},{"t":"东海渔歌补遗鹧鸪天 荠菜","f":"古风","c":["溪上星星小百花。","也随春色斗豪奢。","绿波渺渺天边水，细草盈盈一寸芽。","春有限，遍天涯。","千红万紫互交加。","野人自有真生趣，桃叶携筐亦可夸。"]},{"t":"渔家傲 题双溪垂钓图","f":"古风","c":["垂柳西风吹不起，一竿闲钓双溪水。","濠上高怀差可拟。","烟光里，必有金鳞鲤。","智者从来无彼此，溪山住处皆堪止。","打点琴书游故里。","随缘耳，神仙眷属谁如子。"]},{"t":"浣溪沙 其一 咏双鬟猧儿","f":"七言古诗","c":["怀里温存袖里藏。","蒙茸两耳系金珰。","双鬟小字最相当。","竹叶上窗惊月影，花枝照壁活灯光。","夜深轻睡枕头旁。"]},{"t":"浣溪沙 其二 咏双鬟猧儿","f":"七言古诗","c":["两字柔憨作性情。","十分妩媚特聪明。","得人怜处是天生。","睡去拳拳堪入画，戏时小小可奇擎。","娇音学吠未成声。"]},{"t":"浣溪沙 其一 立春前三日咏盆中茉莉","f":"七言古诗","c":["南北从来气候差。","立春杨柳未舒芽。","洞中先见素馨花。","一线柔风摇翠叶，满枝香雪缀琼葩。","水仙气味略差些。"]},{"t":"浣溪沙 其二 立春前三日咏盆中茉莉","f":"七言古诗","c":["花气袭人喜欲狂。","花前对酒乐非常。","美人名字有余香。","粤海炎天才菉蔌，燕京腊月已芬芳。","从今休说小南强。"]},{"t":"更漏子 其一 忆云林","f":"古风","c":["雨丝丝，风细细。","尽是消魂滋味。","风细细，雨丝丝。","相思十二时。","我忆君，君忆我。","两意一无不可。","君忆我，我忆君。","愁肠似转轮。"]},{"t":"更漏子 其二 忆云林","f":"古风","c":["柳烟柔，花影细。","谁解个中滋味。","乱愁绪，万千丝。","春光能几时。","奈何君，惆怅我。","有甚云为不可。","惆怅我，奈何君。","流年快似轮。"]},{"t":"南乡子 其一 云林招游三官庙看海棠，不果行，用来韵答之","f":"古风","c":["正好看花天。","漠漠轻阴扬柳烟。","最是海棠娇太甚，跹翩。","半要人怜半自怜。"]},{"t":"南乡子 其二 云林招游三官庙看海棠，不果行，用来韵答之","f":"古风","c":["风信莫狂颠。","艳色能留几日鲜。","分付封姨休扫却，嫣然。","似带余酲晚更妍。"]},{"t":"南乡子 其三 云林招游三官庙看海棠，不果行，用来韵答之","f":"古风","c":["小叶碧玲珑。","十二栏干护几重。","不是不知春已去，随风。","且向枝头逞艳红。"]},{"t":"南乡子 其四 云林招游三官庙看海棠，不果行，用来韵答之","f":"古风","c":["花气霭房栊。","芳意憨憨睡思浓。","倦态倩谁扶欲起，冥濛。","和雨和烟入画中。"]},{"t":"南乡子 其五 云林招游三官庙看海棠，不果行，用来韵答之","f":"古风","c":["首夏半晴天。","曲水无由系画船。","恨不共君同一醉，尊前。","饱听飞琼绿绮弦。"]},{"t":"南乡子 其六 云林招游三官庙看海棠，不果行，用来韵答之","f":"古风","c":["尘事惜萦牵。","再到花时又一年。","佳会自应多韵事，相连。","遮莫红妆绿柳边。"]},{"t":"浣溪沙 其一 四时闺词","f":"七言古诗","c":["杨柳丝牵春日迟。","小楼人困落花时。","枕痕自向镜中窥。","帘幕绿阴风荡荡，秋千红索影垂垂。","一声轻脆啭黄鹏。"]},{"t":"浣溪沙 其二 四时闺词","f":"七言古诗","c":["一局棋消夏日长。","林兰初放满盆香。","轻罗小扇引微凉。","花外斜阳蝶晒粉，帘前软语燕窥梁。","兰汤浴罢晚梳妆。"]},{"t":"浣溪沙 其三 四时闺词","f":"七言古诗","c":["爽气怡人秋日清。","银床落叶嫩凉生。","闲邀女伴试瓜灯。","灼灼流萤深院静，纤纤新月一钩明。","蛛丝乞巧祀双星。"]},{"t":"浣溪沙 其四 四时闺词","f":"七言古诗","c":["六出花飞冬日寒。","金炉拨火炷沉檀。","一杯清茗啜龙团。","梅蕊迎风香细细，竹稍压雪叶攒攒。","阿谁忍冻卷帘看。"]},{"t":"柳枝词 其一","f":"七言绝句","c":["正月烧灯暖气融。","天涯何处不春风。","请看八九沿河柳，尽在生机浩荡中。"]},{"t":"柳枝词 其二","f":"七言绝句","c":["二月东风第几场。","狗儿才吐小鹅黄。","输他草色人先见，苦荬茵蔯挑满筐。"]},{"t":"柳枝词 其三","f":"七言绝句","c":["三月清池结绿萍。","杨花飞过杏花汀。","流莺似惜春光尽，啼遍邮传长短亭。"]},{"t":"柳枝词 其四","f":"七言绝句","c":["四月黄梅细雨催。","荼蘼开过枣花开。","柳条不属春拘管，勾引乌衣燕子来。"]},{"t":"柳枝词 其五","f":"七言绝句","c":["五月田家打麦劳。","绿杨多处乱呜蜩。","小船卖酒游人醉，一串活鱼贯柳条。"]},{"t":"柳枝词 其六","f":"七言绝句","c":["六月浓阴系画船。","荷花香到水亭前。","轻雷又送东南雨，摇动青青一树烟。"]},{"t":"柳枝词 其七","f":"七言绝句","c":["七月双星会有期。","盈盈一水隔相思。","何如满树垂杨线，不管纷纷乱乱丝。"]},{"t":"柳枝词 其八","f":"七言绝句","c":["八月凉生桂殿秋。","冰盘高挂柳梢头。","云阶月地知何夕，遮断神仙白玉楼。"]},{"t":"柳枝词 其九","f":"七言绝句","c":["九月凄凄霜气浑。","乱飞黄叶又黄昏。","临歧莫唱折杨柳，风雨重阳最断魂。"]},{"t":"柳枝词 其十","f":"七言绝句","c":["十月漫天雪作花。","柔条叶净剩枯杈。","平桥野渡无人处，栖定冲寒数点鸦。"]},{"t":"柳枝词 其十一","f":"七言绝句","c":["十一月中树尽枯。","一阳复后又扶苏。","青娥不减年时色，装点溪山入画图。"]},{"t":"柳枝词 其十二","f":"七言绝句","c":["十二月来生意含。","无边花木待春三。","新年有象桃符换，天地多情柳色酣。"]}]};